-- ES/DE/FR milestone-translation re-alignment for the 79 tracker
-- milestones, adopting the i18n/{lang}-data.json wording (what the
-- live tracker shows) over D1's independently-translated deep-dive
-- wording -- the "tracker phrasing wins" rule, applied after a
-- numeric-token audit of all 171 mismatched rows confirmed the drift
-- is phrasing-only (identical dates/figures throughout; the 2 flags
-- raised were %-attachment tokenizer artifacts). INSERT OR REPLACE:
-- idempotent, and rows that already matched get identical content.
-- Non-tracker milestones' translations are untouched.

INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-transpose', 'es', 'ViDA — plazo de transposición del Registro Único de IVA', 'Los Estados miembros deben transponer las disposiciones del Registro Único de IVA (SVR) de la Directiva ViDA a su legislación nacional antes de esta fecha, para que el alcance ampliado de la Ventanilla Única (OSS)/Ventanilla Única de Importación (IOSS) y sus aclaraciones conexas puedan aplicarse desde el 1 de enero de 2027. Este plazo es específico del pilar SVR — es distinto de, y anterior a, los calendarios de transposición del pilar de economía de plataformas de ViDA (2028) y de su pilar de facturación electrónica / Requisitos de Reporte Digital (2030).', '["Si vende bienes o servicios B2C transfronterizos dentro de la UE, confirme que su registro OSS/IOSS cubre el alcance ampliado que entra en vigor en enero de 2027","Este plazo no exige por sí mismo la facturación electrónica doméstica — los Estados miembros ya pueden introducir sus propios mandatos de facturación electrónica de forma independiente, bajo las excepciones disponibles desde la entrada en vigor de ViDA en abril de 2025","Siga el calendario de transposición y de facturación electrónica doméstica de su propia autoridad fiscal nacional por separado de este plazo de SVR a nivel de la UE"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-platform-svr-2028', 'es', 'ViDA — entrada en vigor de la economía de plataformas y el Registro Único de IVA', 'Las plataformas digitales que facilitan el alquiler de alojamiento de corta duración y el transporte de pasajeros por carretera pasan a ser el proveedor considerado (deemed supplier) a efectos del IVA cuando el proveedor subyacente no repercute el IVA él mismo (por ejemplo, pequeñas empresas o particulares). Las reformas del Registro Único de IVA entran en vigor en toda la UE, y se aplica una inversión del sujeto pasivo obligatoria cuando un proveedor no está establecido ni registrado a efectos del IVA en el Estado miembro de suministro.', '["Si opera una plataforma que entra en el ámbito de aplicación (alquiler de alojamiento de corta duración o transporte de pasajeros por carretera), confirme sus obligaciones de recaudación y remisión del IVA como proveedor considerado","Si suministra bienes o servicios en un Estado miembro en el que no está registrado a efectos del IVA, confirme si la nueva inversión del sujeto pasivo obligatoria se aplica ahora a sus operaciones","Evalúe si el modelo ampliado de Registro Único de IVA le permite consolidar los registros que mantiene actualmente en varios Estados miembros"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-drr', 'es', 'ViDA — Requisitos de Reporte Digital transfronterizo', 'La facturación electrónica estructurada y los Requisitos de Reporte Digital (DRR) casi en tiempo real pasan a ser obligatorios en toda la UE para las transacciones B2B transfronterizas. Se elimina el Listado Recapitulativo (Modelo 349) y se sustituye por el DRR.', '["Poder emitir facturas electrónicas conformes con EN 16931 dentro de los 10 días posteriores al hecho imponible en ventas B2B intracomunitarias","Incorpore el reporte casi en tiempo real a su flujo de facturación antes de la fecha de entrada en vigor","Retire los procesos del Listado Recapitulativo una vez que el DRR los sustituya"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-align', 'es', 'ViDA — armonización de sistemas nacionales', 'Todos los sistemas nacionales de facturación electrónica y reporte ya existentes (incluidos modelos de compensación consolidados como el SDI de Italia) deben alinearse con la norma armonizada de la UE bajo ViDA.', '["Si opera en un país con su propio sistema de compensación, confirme su plan de alineación con EN 16931/ViDA","Planifique un modelo de reporte único para todos los mercados de la UE en los que opere"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('be-mandate', 'es', 'Facturación electrónica B2B obligatoria vía Peppol', 'La facturación electrónica estructurada pasó a ser obligatoria para las transacciones B2B nacionales entre empresas belgas registradas a efectos del IVA, utilizando el estándar Peppol BIS Billing 3.0 / EN 16931.', '["Conéctese a través de un Punto de Acceso Peppol certificado (o confirme que su proveedor lo es)","Emita y reciba facturas UBL Peppol BIS Billing 3.0 para todas las ventas B2B nacionales","Las facturas en PDF y en papel ya no son válidas — solo se admite el formato estructurado"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('be-penalty', 'es', 'Finaliza el período de tolerancia — se aplican sanciones', 'Finalizó el período de tolerancia administrativa de tres meses; ahora se aplica un régimen de sanciones progresivas (1.500 € / 3.000 € / 5.000 €) a la facturación no conforme.', '["Resuelva de inmediato cualquier vacío pendiente en la incorporación a Peppol — se aplican multas por infracción","Audite las facturas recientes para verificar el cumplimiento del formato estructurado"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('be-ereport', 'es', 'Reporte casi en tiempo real (modelo Peppol de 5 esquinas)', 'Bélgica prevé introducir el reporte digital de IVA casi en tiempo real mediante un modelo Peppol de cinco esquinas, que enviará automáticamente los datos de las facturas a la autoridad fiscal.', '["Empiece a definir el alcance de la capacidad de reporte Peppol de cinco esquinas con su proveedor de Punto de Acceso","Confirme que esto sigue en marcha a medida que se acerque la fecha — las normas de aplicación finales aún están pendientes"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('de-receive', 'es', 'Recepción obligatoria de facturas electrónicas estructuradas', 'Todas las empresas alemanas, sin importar su tamaño, deben poder recibir facturas electrónicas estructuradas conformes con EN 16931 (XRechnung o ZUGFeRD) para transacciones B2B nacionales.', '["Confirme que su proceso de cuentas por pagar puede aceptar XML XRechnung o PDF híbridos ZUGFeRD","Un buzón de correo capaz de recibir facturas estructuradas cumple el mínimo requerido actualmente"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('de-issue-large', 'es', 'Obligación de emisión — empresas con facturación superior a 800.000 €', 'Las empresas con facturación del ejercicio anterior superior a 800.000 € deben emitir facturas electrónicas estructuradas para transacciones B2B nacionales; las facturas solo en PDF ya no son válidas para este grupo.', '["Confirme que su ERP puede generar salida XRechnung o ZUGFeRD 2.1 o superior","Los acuerdos EDI existentes deben cumplir con EN 16931 o transicionar antes de finales de 2027"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('de-issue-all', 'es', 'Obligación de emisión — todas las empresas B2B nacionales', 'La obligación de emisión se extiende a todas las empresas B2B nacionales sin importar la facturación, completando el despliegue por fases de Alemania bajo la Ley de Oportunidades de Crecimiento.', '["Complete el despliegue en cualquier flujo de facturación B2B nacional restante","No se aplicarán más disposiciones transitorias después de esta fecha"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fr-receive', 'es', 'Obligación de recepción + emisión para grandes y medianas empresas', 'Todas las empresas registradas a efectos del IVA en Francia deben poder recibir facturas electrónicas; las grandes y medianas empresas también deben emitirlas a través del portal público (PPF) o una plataforma acreditada (PA, antes PDP).', '["Registre la entrada de su directorio empresarial en el PPF (Portail Public de Facturation)","Elija una Plateforme Agréée acreditada o utilice el portal público gratuito","Configure el e-reporting para transacciones B2C y transfronterizas junto con la facturación electrónica"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fr-issue-all', 'es', 'La obligación de emisión se extiende a todas las empresas restantes', 'Las pequeñas y microempresas, incluidos los autónomos, deben emitir facturas electrónicas, completando la reforma francesa por fases de facturación electrónica y e-reporting B2B.', '["Finalice el software de facturación o la integración con la PA con suficiente antelación a la fecha límite","Confirme que su software admite el formato Factur-X, UBL o CII"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pl-large', 'es', 'KSeF obligatorio — grandes contribuyentes (>200 millones PLN)', 'Los grandes contribuyentes con facturación superior a 200 millones de zlotys se convirtieron en el primer grupo obligado a emitir facturas B2B a través de la plataforma de compensación Krajowy System e-Faktur (KSeF).', '["Intégrese con KSeF vía API utilizando el esquema XML FA(3)","Configure las autorizaciones de KSeF para el personal y cualquier emisor externo"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pl-all', 'es', 'KSeF obligatorio — el resto de las empresas registradas a efectos del IVA', 'El mandato de KSeF se extendió a todas las empresas registradas a efectos del IVA en Polonia restantes (excluyendo a los microempresarios); una factura solo tiene validez legal una vez que KSeF la ha compensado.', '["Confirme que su sistema de facturación genera facturas estructuradas FA(3) válidas","Las notas de corrección (noty korygujące) ya no son válidas — use el proceso de corrección estructurado de KSeF en su lugar","Añada el número de factura de KSeF a las referencias de transferencia bancaria cuando ese requisito entre en vigor (1 de agosto de 2026)"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pl-micro', 'es', 'KSeF obligatorio — microempresarios; comienzan las sanciones', 'Los microempresarios se incorporan al mandato de KSeF, y el período de gracia sobre las sanciones económicas (hasta el 100% del IVA de la factura por incumplimiento) finaliza para todos.', '["Microempresas: confirmen que la integración con KSeF está activa mucho antes de esta fecha","Todas las empresas: resuelvan cualquier vacío de cumplimiento pendiente antes de que se apliquen las sanciones"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('it-sdi', 'es', 'Facturación electrónica B2B/B2C obligatoria vía SDI (en vigor desde 2019)', 'Italia fue el primer Estado miembro de la UE en exigir la facturación electrónica bajo un modelo de compensación para prácticamente todas las transacciones nacionales — B2B, B2C y B2G — a través del Sistema di Interscambio (SDI), usando el formato XML FatturaPA.', '["Confirme que su canal de generación de FatturaPA y transmisión al SDI (PEC, FTP o servicio web) sigue activo","Vigile los cambios de alineación con EN 16931/ViDA antes de la renovación de la excepción del SDI de Italia (hasta 2027) y el plazo de armonización a nivel de la UE de 2035"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sa-wave23', 'es', 'ZATCA Fatoora — Ola 23 (facturación > 750.000 SAR)', 'Las empresas con facturación sujeta a IVA superior a 750.000 SAR en 2022, 2023 o 2024 debían completar la integración de la Fase 2 con la plataforma Fatoora para la compensación en tiempo real.', '["Confirme el plazo de notificación e integración directa de ZATCA para su entidad","Integre su sistema de facturación con la API de Fatoora para la compensación B2B/B2G en tiempo real","Asegúrese de que las facturas incluyan un UUID, código QR y sello criptográfico"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sa-wave24', 'es', 'ZATCA Fatoora — Ola 24 (facturación > 375.000 SAR)', 'El umbral bajó a 375.000 SAR — igualando en la práctica el umbral obligatorio de registro de IVA, incorporando a casi todas las empresas registradas a efectos del IVA a la compensación de la Fase 2.', '["Asuma que está dentro del alcance si está registrado a efectos del IVA; ZATCA notifica a los contribuyentes afectados con unos seis meses de antelación","Emita facturas Estándar (compensación, IVA soportado deducible) para B2B/B2G y facturas Simplificadas para B2C, reportadas en un plazo de 24 horas"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('my-phase4', 'es', 'MyInvois Fase 4 — facturación de RM1m a RM5m', 'Las empresas con facturación anual entre RM1 millón y RM5 millones entraron en el mandato, con un período de relajación (sin sanciones por errores de presentación) extendido hasta el 31 de diciembre de 2027.', '["Regístrese para el acceso al portal o API de MyInvois con LHDN","Determine su fase usando sus cuentas auditadas del ejercicio 2022 o su primera declaración de impuestos disponible","Las facturas electrónicas individuales son obligatorias por encima de RM10.000 — ya no se permite la facturación consolidada para esos importes"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('my-related', 'es', 'Empresas relacionadas/filiales de grupos con RM1m o más', 'Las empresas con facturación inferior a RM1 millón que son filiales o empresas relacionadas de un grupo con RM1 millón o más deben cumplir de todos modos, sin importar sus propios ingresos individuales.', '["Revise la estructura del grupo — la condición de empresa relacionada puede activar el mandato incluso para entidades pequeñas","Registre y pruebe la integración con MyInvois con suficiente antelación a la fecha límite"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('in-threshold', 'es', 'Facturación electrónica GST obligatoria por encima de ₹5 crore de facturación (en vigor desde agosto de 2023)', 'Cualquier empresa registrada a efectos del GST con facturación anual agregada (AATO) superior a ₹5 crore en cualquier ejercicio fiscal desde 2017-18 debe generar facturas electrónicas con un IRN válido para transacciones B2B y de exportación.', '["Confirme la facturación agregada en todos los GSTIN bajo su PAN — solo necesita superar ₹5 crore una vez","Regístrese en un Portal de Registro de Facturas (IRP) — einvoice1.gst.gov.in del NIC o un IRP privado autorizado","Esté atento a una posible reducción del umbral a ₹2 crore, en debate pero aún no notificada"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('in-30day', 'es', 'Ventana de reporte de IRN de 30 días (AATO ≥ ₹10 crore)', 'Las facturas, notas de crédito y notas de débito de más de 30 días de antigüedad ya no pueden reportarse al IRP para generar el IRN — serán rechazadas directamente para contribuyentes con AATO de ₹10 crore o más.', '["Incorpore la ventana de reporte de 30 días a su flujo de trabajo de CxP/CxC","Active la autenticación multifactor en el portal de GST — obligatoria desde abril de 2025"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-fields', 'es', 'Campos CBS/IBS requeridos en NF-e/NFC-e/NFS-e (tasas de prueba)', 'A medida que comienza la reforma tributaria del IVA dual de Brasil, los documentos fiscales electrónicos deben incluir los nuevos campos CBS e IBS con tasas de prueba (0,9 % / 0,1 %) — sin impacto financiero todavía, pero la obligación legal de incluir los datos ya se aplica.', '["Actualice los formatos de facturación a la Nota Técnica 2025.002-RTC (versión más reciente)","Realice pruebas en el entorno de homologación de la SEFAZ antes de la puesta en marcha","Los contribuyentes de Simples Nacional / MEI tienen un plazo ampliado hasta 2027"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-validate', 'es', 'Comienza la validación de campos CBS/IBS — riesgo de rechazo', 'Los sistemas de autorización comienzan a validar rigurosamente los campos CBS/IBS; las facturas con datos incompletos o inconsistentes corren el riesgo de rechazo automático.', '["Audite la salida de facturas para verificar grupos de datos CBS/IBS/IS completos y consistentes","Resuelva rápidamente cualquier rechazo — las facturas bloqueadas detienen el movimiento de mercancías"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-mandatory', 'es', 'Obligación legal plena de reporte para el Régimen Tributario General', 'Bajo la Nota Técnica 2025.002-RTC v1.40, los contribuyentes del Régimen Tributario General deben reportar los grupos IBS y CBS en NF-e y NFC-e con plenos efectos legales.', '["Confirme que su ERP/proveedor de facturación electrónica ha completado las actualizaciones de esquema requeridas","Concilie los datos de CBS/IBS reportados con sus registros contables antes de la aplicación total"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-verifactu-corp', 'es', 'Software de facturación certificado VeriFactu — contribuyentes de sociedades', 'Las empresas sujetas al Impuesto sobre Sociedades deben usar software de facturación certificado VeriFactu (RRSIF) que garantice la integridad, trazabilidad e inmutabilidad de los registros de facturación enviados a la Agencia Tributaria (AEAT).', '["Confirme que su software de facturación está certificado como VeriFactu y genera la cadena de hash y el código QR requeridos","Esta es una obligación independiente del mandato más amplio de facturación electrónica B2B de Crea y Crece detallado abajo"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-verifactu-rest', 'es', 'VeriFactu obligatorio — resto de contribuyentes', 'La obligación VeriFactu se extiende al resto de contribuyentes obligados a llevar registros de facturación, incluidos autónomos y otros profesionales sujetos al IRPF.', '["Autónomos/freelancers: confirmen que el software de facturación certificado está implantado bien antes de esta fecha","Las empresas que ya usan el sistema de reporte en tiempo real SII están exentas de VeriFactu"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-b2b-large', 'es', 'Facturación electrónica B2B Crea y Crece — grandes empresas (>8 millones € de facturación)', 'La facturación electrónica B2B estructurada pasa a ser obligatoria para grandes empresas bajo la ley Crea y Crece, intercambiada a través de plataformas privadas (con copia obligatoria a la plataforma estatal) o la solución pública gratuita (SPFE), en paralelo con VeriFactu.', '["Elija una plataforma de facturación electrónica privada (debe reenviar copia al SPFE) o use la plataforma pública directamente","Confirme formatos conformes con EN 16931 (UBL, Facturae, CII)","Reporte el estado de la factura — aceptada, rechazada o pagada — a la AEAT dentro de 4 días naturales"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-b2b-all', 'es', 'Facturación electrónica B2B Crea y Crece — el resto de empresas', 'El mandato de facturación electrónica B2B se extiende a pymes, autónomos y el resto de empresas registradas a efectos del IVA, completando la reforma de doble vía de facturación electrónica de España.', '["Finalice la elección de plataforma e integración con suficiente antelación a la fecha límite","La Orden Ministerial final aún estaba pendiente a mediados de 2026 — confirme esta fecha más cerca del momento"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uk-mandate', 'es', 'Facturación electrónica obligatoria para todas las facturas con IVA (B2B y B2G)', 'Confirmado en los Presupuestos de 2025, todas las empresas registradas a efectos del IVA deben emitir y recibir facturas electrónicas estructuradas para transacciones B2B y B2G, usando un modelo Peppol descentralizado de cuatro esquinas. El reporte en tiempo real a la HMRC no forma parte de este mandato inicial.', '["Confirme que su software de contabilidad tiene una vía hacia la facturación electrónica basada en Peppol","Esté atento a la hoja de ruta completa de implementación y los estándares técnicos previstos para los Presupuestos de 2026","Empresas de Irlanda del Norte: tengan en cuenta una posible obligación adicional anterior alineada con la UE para el comercio de bienes desde julio de 2030"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ro-established', 'es', 'Modelo de compensación RO e-Factura obligatorio para B2B/B2G (en vigor desde julio de 2024)', 'Rumanía opera un modelo de compensación centralizado (CTC): las facturas B2B y B2G deben ser validadas y selladas digitalmente por la ANAF a través de RO e-Factura antes de tener efectos legales. El reporte B2C siguió desde enero de 2025.', '["Confirme el registro en RO e-Factura y la generación de facturas XML conformes con RO_CIUS","El plazo de transmisión es de 5 días hábiles desde la emisión (reducido desde 5 días naturales en enero de 2026)"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ro-sme', 'es', 'La aplicación plena se extiende a los pequeños contribuyentes (<500.000 € de facturación)', 'Tras un retraso confirmado, los pequeños contribuyentes con facturación inferior a 500.000 € quedan plenamente sujetos a la aplicación y sanciones de e-Factura, en igualdad de condiciones con las empresas más grandes.', '["Estandarice las direcciones de clientes y los códigos de país/ISO antes de la fecha límite","Confirme que su herramienta de facturación aplica la regla de transmisión de 5 días hábiles"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uae-pilot', 'es', 'Comienza la fase piloto voluntaria de facturación electrónica', 'Se abrió la participación voluntaria antes del mandato, permitiendo a las empresas probar la conectividad con un Proveedor de Servicios Acreditado (ASP) y el formato de factura PINT AE sin riesgo antes de que se apliquen sanciones.', '["Considere unirse al piloto voluntario para resolver problemas de integración con el ASP antes de la fase obligatoria","Siga las actualizaciones de orientación técnica de la Autoridad Federal de Impuestos (FTA)"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uae-asp', 'es', 'Plazo de nombramiento de ASP — empresas con facturación ≥ 50 millones AED', 'Las empresas con facturación de 50 millones AED o más deben haber nombrado un Proveedor de Servicios Acreditado (ASP) antes de la puesta en marcha de enero de 2027 (plazo ampliado desde el 31 de julio de 2026).', '["Seleccione y contrate un Proveedor de Servicios Acreditado por la FTA","Comience las pruebas de integración PINT AE (UBL 2.1) con su ASP"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uae-phase1', 'es', 'Puesta en marcha obligatoria de la Fase 1 — facturación ≥ 50 millones AED', 'La facturación electrónica estructurada pasa a ser obligatoria para grandes empresas, transmitida a través de un ASP por la red Peppol en formato PINT AE, con una copia en tiempo real reportada a la FTA.', '["Complete la integración con el ASP y las pruebas de extremo a extremo antes de la puesta en marcha","Asegúrese de que las facturas incluyan todos los campos de datos exigidos por la FTA — el PDF y el papel ya no son válidos"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uae-phase2', 'es', 'El mandato se extiende a todas las demás empresas registradas a efectos del IVA', 'El mandato de facturación electrónica se amplía para cubrir a todas las empresas registradas a efectos del IVA restantes para transacciones B2B/B2G, con obligaciones específicas de G2B/B2G a partir de octubre de 2027.', '["Confirme el estado de registro de IVA y nombre un ASP con suficiente antelación a esta fecha","Las transacciones intragrupo dentro de un mismo grupo de IVA de los EAU tienen una transición ampliada hasta el 1 de enero de 2029"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('mx-cfdi', 'es', 'Modelo de compensación CFDI obligatorio (versión actual CFDI 4.0)', 'México opera uno de los sistemas de compensación de facturación electrónica más maduros del mundo: cada factura debe ser validada y sellada digitalmente (timbrada) por un PAC autorizado antes de tener validez legal, en formato XML CFDI 4.0.', '["Asegure la conectividad con el PAC y el mapeo actualizado de campos CFDI 4.0 (Anexo 20) — el RFC/nombre/Régimen Fiscal del receptor debe coincidir exactamente con los registros del SAT","Adjunte los complementos requeridos cuando corresponda (Carta Porte para transporte de mercancías, Pagos para pagos a plazos, Comercio Exterior para exportaciones)","Conserve las facturas XML y los acuses de recibo del PAC durante al menos 5 años"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('mx-reform', 'es', 'Reforma fiscal de 2026 — requisitos de autenticidad y aplicación más estrictos', 'Una reforma fiscal vigente desde enero de 2026 reforzó las facultades de fiscalización del SAT, añadiendo controles de autenticidad más estrictos y responsabilidad penal por CFDI falsos o simulados.', '["Mantenga evidencia que respalde la autenticidad de las transacciones — contratos, comprobantes de entrega, registros de pago — ya que el SAT puede solicitarlos en un plazo de 5 días hábiles","Revise la documentación de defensa de CFDI y los procedimientos de cancelación dadas las nuevas disposiciones de responsabilidad penal"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-ncereceive', 'es', 'Organismos federales obligados a recibir facturas Peppol (en vigor desde julio de 2022)', 'Todas las Entidades No Corporativas de la Mancomunidad (organismos federales) están obligadas a recibir facturas Peppol desde el 1 de julio de 2022. No existe un mandato general B2B, pero la adopción gubernamental sigue acelerándose.', '["Proveedores de organismos federales: conéctense a través de un Punto de Acceso Peppol acreditado por la ATO","Las facturas entregadas vía Peppol pueden pagarse en 5 días en lugar de los 20 estándar"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-30pct', 'es', 'El 30 % de las facturas de organismos federales debe procesarse vía Peppol', 'Las Entidades No Corporativas de la Mancomunidad deben tener al menos el 30 % de las facturas de proveedores recibidas fluyendo por la red Peppol, camino hacia la automatización total en diciembre de 2026.', '["Si abastece a organismos federales australianos, confirme que su facturación está habilitada para Peppol","Use el formato PINT A-NZ — el único estándar admitido desde el 15 de mayo de 2025"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-automate', 'es', 'Los organismos federales deben automatizar el envío y procesamiento de facturas electrónicas', 'Las Entidades No Corporativas de la Mancomunidad deben poder procesar automáticamente las facturas electrónicas recibidas y enviar facturas electrónicas, con reporte trimestral de avance a la Autoridad Peppol Australiana.', '["Confirme que su configuración de facturación electrónica admite el procesamiento totalmente automatizado, sin intervención manual","Los proveedores del gobierno deben esperar ciclos de pago más rápidos a medida que se implanta la automatización"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nz-central', 'es', 'Los organismos del gobierno central obligados a recibir facturas electrónicas (en vigor desde marzo de 2022)', 'Todos los organismos públicos centrales están obligados a recibir facturas Peppol desde marzo de 2022, administrado por el MBIE como la Autoridad Peppol de Nueva Zelanda.', '["Proveedores de organismos centrales: configuren la capacidad de facturación Peppol a través de un Punto de Acceso acreditado"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nz-2000', 'es', 'Los organismos que gestionan más de 2.000 facturas/año deben enviar y recibir facturas electrónicas', 'Los organismos gubernamentales que procesan más de 2.000 facturas comerciales nacionales al año deben poder tanto enviar como recibir facturas electrónicas estructuradas, y pagar el 95 % de ellas en un plazo de 5 días hábiles.', '["Confirme el cumplimiento del formato PINT A-NZ — obligatorio para la facturación electrónica gubernamental desde mayo de 2025","Compruebe si su cliente gubernamental se encuentra dentro de este umbral de volumen"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nz-largesupplier', 'es', 'Los grandes proveedores (facturación >33 millones NZD) deben enviar facturas electrónicas al gobierno', 'Los proveedores con facturación superior a 33 millones NZD en cada uno de los dos ejercicios contables anteriores deben enviar facturas electrónicas vía Peppol para facturas de comercio nacional a compradores gubernamentales.', '["Evalúe si su facturación supera el umbral de 33 millones NZD","Intégrese con un Punto de Acceso Peppol con suficiente antelación a la fecha límite"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-voluntary2025', 'es', 'GST InvoiceNow obligatorio — nuevos registrantes voluntarios de GST (dentro de los 6 meses de constitución)', 'La primera fase obligatoria de GST InvoiceNow exigió a las empresas que se registraron voluntariamente para el GST dentro de los seis meses posteriores a su constitución que transmitieran los datos de facturación a la IRAS a través de la red InvoiceNow basada en Peppol.', '["Nuevos registrantes de GST que califiquen: configuren una Solución Lista para InvoiceNow y un ID Peppol en el momento del registro"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-allvoluntary', 'es', 'El mandato se extiende a todos los nuevos registrantes voluntarios de GST', 'Todos los nuevos registrantes voluntarios de GST, sin importar la fecha de constitución o la estructura empresarial, deben adoptar InvoiceNow como condición del registro de GST.', '["Incorpore la configuración de InvoiceNow a su solicitud de registro de GST a partir de esta fecha","Use la calculadora de fecha de implementación de la IRAS si no está seguro de qué fase le corresponde"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-existing2028', 'es', 'Comienza el despliegue por fases para empresas ya registradas a efectos del GST', 'Las empresas ya registradas a efectos del GST comienzan a incorporarse a GST InvoiceNow según un calendario por fases que culmina en la adopción total en 2031. La IRAS notificará a las empresas afectadas su fecha específica durante 2026.', '["Use la Calculadora de Fecha de Implementación de GST InvoiceNow de la IRAS para determinar su fecha aplicable","Esté atento a la notificación directa de la IRAS (prevista para mediados de 2026)"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-full2031', 'es', 'Adopción total — todas las empresas registradas a efectos del GST', 'Para esta fecha, toda empresa registrada a efectos del GST en Singapur, incluidas las grandes multinacionales, debe transmitir los datos de facturación vía InvoiceNow.', '["Planifique la integración con suficiente antelación — hay subvenciones gubernamentales transitorias disponibles para apoyar la adopción"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sk-voluntary', 'es', 'Comienza el período de transición voluntario de facturación/reporte electrónico', 'Las empresas pueden registrarse voluntariamente para probar la facturación electrónica estructurada y el reporte antes del mandato de enero de 2027, usando un modelo descentralizado de "5 esquinas" basado en Peppol.', '["Regístrese para la participación voluntaria con la Administración Financiera para probar integraciones con antelación","Confirme que su software de contabilidad puede generar XML UBL Peppol BIS 3.0"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sk-mandate', 'es', 'Facturación electrónica B2B/B2G nacional obligatoria y reporte casi en tiempo real', 'La facturación electrónica estructurada y el reporte en tiempo real pasan a ser obligatorios para transacciones B2B y B2G nacionales entre contribuyentes eslovacos de IVA, usando puntos de acceso certificados "Digital Postman" en una red basada en Peppol.', '["Seleccione un proveedor de Digital Postman (punto de acceso certificado) aprobado","A partir de 2027, no se podrán deducir el IVA soportado en facturas entrantes no conformes","Nota: la facturación electrónica transfronteriza sigue después, bajo el calendario de ViDA de la UE desde julio de 2030"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pe-established', 'es', 'Facturación electrónica (CPE) obligatoria para todos los contribuyentes (en vigor desde junio de 2022)', 'Perú opera uno de los sistemas de facturación electrónica más maduros de América Latina. Los Comprobantes de Pago Electrónicos (CPE) deben emitirse en XML UBL 2.1, firmados digitalmente, y validados por la SUNAT o un Operador de Servicios Electrónicos (OSE) autorizado antes de tener validez legal.', '["Use un Proveedor de Servicios Electrónicos (PSE) aprobado para generar y firmar CPE","Envíe las facturas electrónicas a la SUNAT dentro de los 3 días naturales posteriores a la emisión","Archive las facturas XML y las confirmaciones de recepción CDR durante al menos 5 años"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cl-established', 'es', 'Documentos Tributarios Electrónicos (DTE) obligatorios para todas las empresas (en vigor desde 2018)', 'Todas las empresas chilenas deben emitir Documentos Tributarios Electrónicos (DTE) — incluyendo facturas (B2B) y boletas (B2C) — validados por el Servicio de Impuestos Internos (SII).', '["Confirme que su sistema de emisión de DTE está autorizado y conectado al SII","Para ventas superiores a 135 UF, la boleta electrónica debe identificar al comprador por RUT y nombre"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cl-digital-delivery', 'es', 'Se requiere entrega digital de la boleta electrónica cuando no hay impresora disponible', 'Las empresas sin capacidad de impresión deben entregar la boleta electrónica digitalmente — por correo electrónico, SMS, WhatsApp, código QR u otro canal electrónico equivalente — en lugar de omitir la entrega por completo.', '["Si carece de impresión en el punto de venta, configure ahora un canal de entrega electrónica (correo/SMS/QR)","Las empresas con impresoras generalmente deben seguir entregando la representación impresa"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ie-phase1', 'es', 'Fase 1 — las grandes corporaciones deben emitir facturas electrónicas; todas las empresas deben poder recibirlas', 'Las grandes corporaciones registradas a efectos del IVA gestionadas por la División de Grandes Corporaciones de Revenue deben emitir facturas electrónicas estructuradas y reportar un subconjunto de datos de transacciones para ventas B2B nacionales. A partir de esta fecha, todas las empresas deben estar técnicamente capacitadas para recibir facturas electrónicas estructuradas.', '["Grandes corporaciones: evalúen la preparación de su ERP para la facturación estructurada EN 16931 vía Peppol desde ahora","Todas las empresas: confirmen que sus sistemas pueden recibir facturas electrónicas estructuradas — los PDF ya no serán aceptados de proveedores dentro del alcance"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ie-phase2', 'es', 'Fase 2 — el mandato se extiende a todas las empresas registradas a efectos del IVA en comercio intracomunitario', 'La obligación nacional de facturación electrónica y reporte se extiende a todas las empresas restantes registradas a efectos del IVA que participan en el comercio B2B transfronterizo dentro de la UE, antes del pleno cumplimiento de ViDA de la UE en julio de 2030.', '["Las empresas que comercian de forma transfronteriza dentro de la UE deben comenzar a planificar la integración con Peppol","Esté atento a las directrices detalladas de Revenue, previstas con bastante antelación a cada fase"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('no-issue', 'es', 'Emisión obligatoria de facturas electrónicas B2B (EHF 3.0 / Peppol BIS)', 'Tras la promulgación de las enmiendas a la Ley de Contabilidad, todas las empresas con obligaciones contables noruegas deben emitir facturas electrónicas estructuradas (formato EHF) a otras empresas registradas en el directorio ELMA.', '["Regístrese en ELMA (el directorio noruego de receptores Peppol) si aún no figura en él","Confirme que su software de facturación admite la salida EHF 3.0 / Peppol BIS","Las facturas B2B en PDF y en papel dejarán de ser válidas para las transacciones dentro del alcance"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('no-receive', 'es', 'Recepción obligatoria de facturas electrónicas y contabilidad totalmente digital', 'El mandato se extiende a la recepción de facturas electrónicas estructuradas y al mantenimiento de registros contables totalmente digitales, completando la reforma noruega en dos fases.', '["Planifique la migración a un sistema de contabilidad digital aprobado con suficiente antelación a esta fecha","Confirme que los sistemas de CxP pueden recibir y procesar automáticamente facturas EHF/Peppol"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('dk-established', 'es', 'Ley de Contabilidad Digital en vigor — empresas medianas/grandes (en vigor desde julio de 2024)', 'Las empresas medianas y grandes que presentan informes anuales deben usar un sistema de contabilidad digital certificado capaz de enviar y recibir facturas electrónicas estructuradas (OIOUBL o Peppol BIS 3.0) y generar archivos SAF-T a petición.', '["Confirme que su sistema de contabilidad figura en la lista certificada de la Autoridad Empresarial Danesa, o garantice el cumplimiento usted mismo si usa un sistema personalizado","Mantenga registros digitales durante 5 años con copia de seguridad automatizada externa"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('dk-small', 'es', 'Las pequeñas empresas (facturación >300.000 DKK) con sistemas personalizados deben cumplir', 'Las pequeñas empresas y empresas unipersonales que superan los 300.000 DKK de facturación en dos años consecutivos, que usan sistemas de contabilidad no registrados ("personalizados"), quedan plenamente sujetas a los requisitos digitales de la Ley de Contabilidad.', '["Compruebe si su facturación ha superado el umbral de 300.000 DKK en los últimos dos ejercicios fiscales","Las empresas con sistemas registrados/certificados ya debían cumplir desde enero de 2026"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('se-b2g', 'es', 'Facturación electrónica B2G obligatoria para todas las entidades públicas (en vigor desde 2019)', 'Todas las autoridades contratantes y entidades públicas de Suecia deben poder recibir facturas electrónicas conformes con EN 16931, siendo Peppol BIS Billing 3.0 el formato recomendado (y cada vez más exigido) a medida que se retiran formatos heredados como Svefaktura.', '["Proveedores de entidades públicas suecas: usen Peppol BIS Billing 3.0 cuando sea posible — los formatos heredados SFTI/EDIFACT están siendo retirados","Aún no existe un mandato B2B nacional — vea la entrada siguiente sobre la alineación esperada con la UE"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('se-b2b-expected', 'es', 'Se espera la facturación electrónica B2B transfronteriza bajo ViDA de la UE', 'Suecia aún no ha legislado un mandato nacional de facturación electrónica B2B; Skatteverket, DIGG y Bolagsverket han pedido al gobierno que evalúe uno, pero el único plazo firme actualmente sobre la mesa es el requisito transfronterizo de ViDA a nivel de la UE.', '["Siga de cerca cualquier anuncio de mandato nacional — aún está pendiente una propuesta formal del gobierno","Los comerciantes transfronterizos deben planificar igualmente la preparación EN 16931/Peppol antes del plazo de 2030 a nivel de la UE"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cn-nationwide', 'es', 'La factura electrónica totalmente digitalizada (e-fapiao) se implanta a nivel nacional (en vigor desde diciembre de 2024)', 'La Administración Estatal de Tributación (STA) completó la implantación nacional de facturas electrónicas totalmente digitalizadas (e-fapiao), otorgándoles la misma validez legal que las facturas en papel y sustituyendo las fases piloto anteriores del Sistema Fiscal de Oro.', '["Configure una cuenta fiscal digital con la STA para emitir y recibir e-fapiao","Confirme que los sistemas ERP/facturación pueden generar e-fapiao con los campos obligatorios en chino simplificado y renderizado OFD/XML","Conserve el código de factura de la STA, la firma digital, el código QR dinámico y la marca de tiempo de compensación de cada factura"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cn-paper-phaseout', 'es', 'Se acelera la eliminación regional de las facturas en papel', 'Autoridades fiscales locales en varias regiones (por ejemplo, Dalian, con efecto desde el 1 de julio de 2026) han comenzado a eliminar tipos específicos de facturas en papel supervisadas fiscalmente en favor de la e-fapiao, y se espera que más regiones sigan este ejemplo durante 2026.', '["Consulte los anuncios de su oficina local de la STA sobre las fechas de eliminación del papel específicas de su región y sector","Las facturas emitidas antes de la fecha límite de una región siguen siendo válidas, pero la nueva emisión en papel puede bloquearse a partir de esa fecha"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('hr-b2b', 'es', 'Fiskalizacija 2.0 — facturación y reporte electrónico obligatorios para empresas registradas a efectos del IVA', 'La reforma "Fiscalización 2.0" de Croacia hizo obligatoria la facturación electrónica estructurada (emisión y recepción) y el e-reporting en tiempo real para todos los contribuyentes croatas registrados a efectos del IVA, sumándose al mandato de facturación electrónica B2G ya vigente desde 2019.', '["Registre una dirección AMS y contrate un intermediario de información o punto de acceso certificado","Asegúrese de que los sistemas ERP generen XML UBL 2.1 válido alineado con el CIUS HR-FISK 2.0 (incluidos códigos KPD de 6 dígitos y OIB)","Incorpore el flujo de trabajo de fiscalización del comprador a 5 días y el e-reporting mensual antes del día 20","Archive las facturas XML originales durante 11 años"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('hr-nonvat', 'es', 'El mandato se extiende a entidades no registradas a efectos del IVA y organismos públicos', 'La obligación de emitir (no solo recibir) facturas electrónicas estructuradas y datos de e-reporting se extiende a entidades no registradas a efectos del IVA — pequeñas empresas, autónomos y ciertos organismos públicos/presupuestarios.', '["Empresas y autónomos no registrados a efectos del IVA: confirmen la capacidad de emisión de facturación electrónica con suficiente antelación a esta fecha","Los organismos públicos no registrados a efectos del IVA deben completar la integración del punto de acceso durante 2026"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('us-federal-b2g', 'es', 'Los organismos federales deben gestionar las facturas electrónicamente (B2G, en vigor desde 2018)', 'La Oficina de Gestión y Presupuesto ordenó a los organismos federales pasar a la facturación electrónica para las contrataciones apropiadas. La mayoría usan ahora la Plataforma de Procesamiento de Facturas (IPP) del Tesoro — pero no existe un formato único obligatorio, ni ningún mandato B2B nacional.', '["Si vende a organismos federales, confirme que está configurado en la IPP o en el canal de facturación electrónica designado por su organismo","Conserve los registros de facturas electrónicas para que sigan siendo accesibles, precisos y legibles según las directrices del IRS (Publicación 583)"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('us-dbnalliance', 'es', 'Red de intercambio de facturas electrónicas B2B DBNAlliance activa (voluntaria, impulsada por el mercado)', 'La Digital Business Networks Alliance (DBNAlliance) — una organización sin ánimo de lucro surgida de un piloto de la Reserva Federal / Business Payments Coalition — opera ahora una red de cuatro esquinas al estilo Peppol para el intercambio voluntario y estructurado de facturas electrónicas B2B en EE. UU. y Canadá. Ninguna ley federal o estatal exige su adopción.', '["Considere conectarse a través de un proveedor de servicios certificado por DBNAlliance antes de cualquier mandato futuro","Si comercia con socios en países que ya exigen la facturación electrónica (UE, México, Brasil, etc.), asegúrese de que sus sistemas puedan seguir produciendo sus formatos requeridos"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ca-federal-b2g', 'es', 'Todos los proveedores del gobierno federal deben facturar electrónicamente (B2G, en vigor desde 2022)', 'Desde abril de 2022, Public Services and Procurement Canada (PSPC) exige a los proveedores presentar facturas electrónicamente a través de su solución de contratación electrónica basada en SAP Ariba. No existe ningún mandato federal de facturación electrónica B2B.', '["Si abastece al Gobierno de Canadá, regístrese en SAP Ariba a través de CanadaBuys","Conserve las facturas electrónicas durante al menos 6 años según los requisitos de conservación de registros de la CRA"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ca-watch', 'es', 'La CRA estudia un posible mandato de facturación electrónica B2B (sin mandato promulgado)', 'La Agencia de Ingresos de Canadá realizó una investigación con partes interesadas sobre un posible mandato nacional de facturación electrónica B2B. No se ha seguido de ninguna legislación ni plazo firme — las normas de GST/HST siguen siendo neutrales en cuanto al formato, y las facturas en papel, PDF y EDI son actualmente todas aceptables siempre que contengan la información fiscal requerida.', '["No se requiere ninguna acción hoy más allá de las buenas prácticas de conservación de registros","Siga los futuros anuncios de la CRA / Finance Canada, especialmente a medida que crece la adopción de la red DBNAlliance en Canadá"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-b2g-large', 'es', 'Facturación electrónica B2G obligatoria para grandes empresas (en vigor desde enero de 2021)', 'Las grandes empresas que suministran a organismos de la administración pública deben emitir facturas electrónicas estructuradas en el formato nacional CIUS-PT (una implementación portuguesa de la norma EN 16931, mediante UBL 2.1 o CEFACT CII), transmitidas a través de la plataforma FE-AP gestionada por eSPap u otro canal aprobado. Portugal no tiene un mandato general de facturación electrónica B2B o B2C — este requisito se aplica específicamente al suministro al sector público.', '["Confirme que su sistema de facturación puede generar XML estructurado CIUS-PT válido, no solo una representación en PDF","Conéctese a FE-AP o a un canal alternativo aprobado para transmitir facturas a organismos públicos"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-b2g-sme', 'es', 'El mandato B2G se extiende a pequeñas, medianas y microempresas', 'El requisito de facturación electrónica estructurada CIUS-PT para proveedores del sector público, que antes solo se aplicaba a las grandes empresas, se extiende ahora a pequeñas, medianas y microempresas. Por separado, independientemente del tamaño de la empresa o de si se aplica B2G, todas las facturas — en papel o electrónicas — deben emitirse ya con software certificado por la AT y llevar un código ATCUD, un código QR y una cadena de hash para garantizar la autenticidad.', '["Si suministra a algún organismo público portugués y aún no emite facturas estructuradas CIUS-PT, esto ya es una brecha de cumplimiento activa, no futura","Independientemente de su situación B2G, confirme que su software de facturación está en la lista certificada por la AT — usar software no certificado invalida una factura independientemente de su contenido"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-qes', 'es', 'Se exige la Firma Electrónica Cualificada (QES) para las facturas en PDF', 'Las facturas en PDF en transacciones B2B y B2C requerirán una Firma Electrónica Cualificada de un prestador de servicios de confianza cualificado registrado en la UE para seguir siendo legalmente válidas — aplazado desde una fecha original de 2026 mediante el Presupuesto del Estado 2026. Hasta el 31 de diciembre de 2026, las facturas en PDF emitidas por software certificado con ATCUD y código QR siguen siendo válidas sin QES. Esta capa se aplica además de, no en lugar de, los requisitos de software certificado/ATCUD/QR/SAF-T ya vigentes.', '["Identifique un prestador de servicios de confianza cualificado registrado en la UE para la QES bien antes del plazo de 2027 — es un paso de contratación diferenciado, no una opción de software","No asuma que el cumplimiento de los requisitos existentes de ATCUD/QR/software certificado cubre esto — la QES es una capa nueva y adicional específicamente para las facturas en PDF"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fi-b2g', 'es', 'Facturación electrónica B2G obligatoria (en vigor desde abril de 2020)', 'Todos los proveedores que facturen a organismos gubernamentales finlandeses deben enviar facturas electrónicas salvo acuerdo en contrario — uno de los regímenes B2G más maduros de Europa, con alrededor del 99% de las facturas a compradores públicos ya electrónicas. Finlandia no tiene un mandato general de facturación electrónica B2B o B2C: la facturación electrónica B2B nacional sigue siendo totalmente voluntaria, aunque las empresas con una facturación superior a 10.000 € tienen el derecho legal de exigir facturas electrónicas a sus proveedores en virtud de la Ley de Facturación Electrónica 241/2019.', '["Si suministra a algún organismo público finlandés, confirme que puede enviar facturas electrónicas — esto lleva siendo la norma durante años, no es un requisito nuevo","Para el B2B nacional, no asuma que existe un mandato legal — compruebe en su lugar los requisitos contractuales específicos de su cliente"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fi-en-standard', 'es', 'El Estado exige facturas electrónicas conformes con EN 16931 (en vigor desde abril de 2021)', 'Desde esta fecha, los organismos gubernamentales finlandeses solo aceptan facturas electrónicas conformes con la Norma Europea (EN 16931) — los formatos no estándar ya no son suficientes para la facturación B2G, aunque la propia facturación electrónica ya llevaba un año siendo obligatoria. Tanto Finvoice 3.0 como TEAPPSXML 3.0 pueden generar facturas conformes con EN, pero el cumplimiento no es automático — las empresas deben verificar que la salida de su software realmente cumple la norma, no asumirlo por defecto.', '["Confirme que la salida de Finvoice 3.0 o TEAPPSXML 3.0 de su software realmente cumple con EN 16931, no solo de forma superficial","Consulte el directorio Verkkolaskuosoite para confirmar qué operador/portal de facturación electrónica llega a una determinada contraparte del sector público — no existe una única plataforma central"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fi-vida', 'es', 'Facturación electrónica B2B intracomunitaria obligatoria bajo el ViDA de la UE', 'Finlandia no tiene actualmente ningún mandato nacional de facturación electrónica B2B, y ninguno está confirmado antes de este plazo a escala de la UE, bajo el cual las transacciones B2B intracomunitarias requerirán facturación electrónica estructurada y reporte digital en todos los Estados miembros. El gobierno finlandés ha indicado que planea comenzar los preparativos alrededor de 2028, y un mandato nacional podría llegar después de este plazo de la UE en lugar de antes — una postura genuinamente diferente a la de la mayoría de los demás países de este seguimiento, que se están adelantando considerablemente al suelo de la UE de 2030.', '["No asuma que Finlandia seguirá el mismo calendario de mandato nacional que sus vecinos nórdicos — a día de hoy, no se ha fijado ninguna fecha de mandato nacional","Vuelva a consultar esta página periódicamente en lugar de tratar la ausencia actual de mandato como un estado permanente — los preparativos de 2028 podrían revelar un calendario nacional más firme"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('lx-b2g', 'es', 'El mandato de facturación electrónica B2G está plenamente vigente', 'La implementación escalonada de la facturación electrónica B2G de Luxemburgo se completó: todos los operadores económicos, incluidas las pequeñas empresas y las de reciente creación, deben ahora emitir facturas electrónicas Peppol BIS Billing 3.0 / EN 16931 a los organismos públicos de Luxemburgo.', '["Confirme que su Punto de Acceso Peppol (o la opción de carga manual de guichet.lu) está configurado para cada contrato público que suministre","Se exigen facturas estructuradas EN 16931 para toda la contratación pública — no se aplica ningún umbral"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('lx-b2b-receipt', 'es', 'Propuesta: la recepción de facturas electrónicas B2B pasa a ser obligatoria', 'Según el proyecto de ley aprobado por el Consejo de Gobierno de Luxemburgo el 17 de julio de 2026, todas las empresas estarían obligadas a poder recibir facturas electrónicas estructuradas para las transacciones B2B nacionales a través de una red Peppol de cuatro esquinas, antes de que entre en vigor la obligación de emisión.', '["Siga la tramitación del proyecto en el Parlamento — todavía es un proyecto de ley, no está en vigor","Confirme que su sistema de facturación/ERP ya puede recibir facturas Peppol BIS Billing 3.0"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('lx-b2b-issue-large', 'es', 'Propuesta: emisión de facturas electrónicas B2B para grandes y medianas empresas', 'Las empresas grandes y medianas estarían obligadas a emitir, y no solo recibir, facturas electrónicas B2B nacionales estructuradas a través de Peppol — seis meses después de que la obligación de recepción entre en vigor para todos.', '["Proveedores de mayor tamaño: inicien la incorporación al Punto de Acceso Peppol con bastante antelación a esta fecha","Confirme su clasificación actual por tamaño de empresa, ya que determina qué plazo se aplica"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('lx-b2b-issue-all', 'es', 'Propuesta: la emisión de facturas electrónicas B2B se generaliza', 'Las empresas restantes, incluidas las pymes, estarían obligadas a emitir facturas electrónicas B2B nacionales estructuradas, completando así el despliegue escalonado anunciado junto con las reformas del IVA en la era digital (ViDA) de la UE.', '["Pymes: este es el plazo que les aplica, 18 meses después de que comience la obligación de recepción","No se prevé ningún reporte de IVA en tiempo real a nivel nacional junto con esta medida — Luxemburgo mantiene el modelo de interoperabilidad Peppol, no un sistema de compensación"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-transpose', 'de', 'ViDA — Umsetzungsfrist für die einheitliche USt-Registrierung', 'Die Mitgliedstaaten müssen die Bestimmungen zur einheitlichen USt-Registrierung (Single VAT Registration, SVR) der ViDA-Richtlinie bis zu diesem Datum in nationales Recht umsetzen, damit der erweiterte Anwendungsbereich des One-Stop-Shop (OSS)/Import-One-Stop-Shop (IOSS) und die zugehörigen Klarstellungen ab dem 1. Januar 2027 gelten können. Diese Frist betrifft ausschließlich den SVR-Bereich — sie unterscheidet sich von den Umsetzungsfristen für ViDAs Plattformwirtschafts-Bereich (2028) und den Bereich E-Invoicing/Digitale Meldepflichten (2030) und liegt zeitlich vor diesen.', '["Wenn Sie grenzüberschreitend B2C-Waren oder -Dienstleistungen innerhalb der EU verkaufen, stellen Sie sicher, dass Ihre OSS-/IOSS-Registrierung den ab Januar 2027 geltenden erweiterten Anwendungsbereich abdeckt","Diese Frist verlangt für sich genommen keine inländische E-Rechnungsstellung — Mitgliedstaaten können bereits seit dem Inkrafttreten von ViDA im April 2025 unabhängig eigene E-Invoicing-Mandate einführen","Verfolgen Sie den Umsetzungs- und E-Invoicing-Zeitplan Ihrer eigenen nationalen Steuerbehörde getrennt von dieser EU-weiten SVR-Frist"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-platform-svr-2028', 'de', 'ViDA — Start der Plattformwirtschafts- und SVR-Regeln', 'Digitale Plattformen, die die kurzfristige Vermietung von Unterkünften und den Personenstraßenverkehr vermitteln, gelten für Mehrwertsteuerzwecke als fiktiver Lieferer, wenn der eigentliche Anbieter selbst keine Mehrwertsteuer erhebt (z. B. Kleinunternehmer oder Privatpersonen). Die Reformen zur einheitlichen USt-Registrierung treten EU-weit in Kraft, und ein verpflichtendes inländisches Reverse-Charge-Verfahren gilt, wenn ein Lieferer im Mitgliedstaat der Lieferung nicht ansässig oder nicht umsatzsteuerlich registriert ist.', '["Wenn Sie eine betroffene Plattform betreiben (kurzfristige Unterkunftsvermietung oder Personenstraßenverkehr), klären Sie Ihre Pflichten zur Erhebung und Abführung der Umsatzsteuer als fiktiver Lieferer","Wenn Sie Waren oder Dienstleistungen in einem Mitgliedstaat erbringen, in dem Sie nicht umsatzsteuerlich registriert sind, prüfen Sie, ob das neue verpflichtende Reverse-Charge-Verfahren nun auf Ihre Umsätze anwendbar ist","Prüfen Sie, ob Sie mit dem erweiterten Modell der einheitlichen USt-Registrierung mehrere derzeit gehaltene Registrierungen in verschiedenen Mitgliedstaaten konsolidieren können"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-drr', 'de', 'ViDA — grenzüberschreitende digitale Meldepflichten', 'Strukturiertes E-Invoicing und nahezu Echtzeit-Meldepflichten (Digital Reporting Requirements, DRR) werden EU-weit für grenzüberschreitende B2B-Transaktionen verpflichtend. Die Zusammenfassende Meldung entfällt und wird durch DRR ersetzt.', '["Stellen Sie sicher, dass Sie EN-16931-konforme E-Rechnungen innerhalb von 10 Tagen nach dem Steuertatbestand für innergemeinschaftliche B2B-Verkäufe ausstellen können","Integrieren Sie die Nahezu-Echtzeit-Meldung frühzeitig in Ihre Rechnungsstellungsprozesse","Stellen Sie die Prozesse zur Zusammenfassenden Meldung ein, sobald DRR sie ersetzt"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-align', 'de', 'ViDA — Harmonisierung nationaler Systeme', 'Alle bereits bestehenden nationalen E-Invoicing- und Meldesysteme (einschließlich etablierter Clearing-Modelle wie Italiens SDI) müssen an den harmonisierten EU-ViDA-Standard angeglichen werden.', '["Falls Sie in einem Land mit eigenem Clearing-System tätig sind, prüfen Sie dessen Plan zur Angleichung an EN 16931/ViDA","Planen Sie ein einheitliches Meldemodell für alle EU-Märkte, in denen Sie tätig sind"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('be-mandate', 'de', 'Verpflichtendes B2B-E-Invoicing über Peppol', 'Strukturiertes E-Invoicing wurde für inländische B2B-Transaktionen zwischen belgischen umsatzsteuerpflichtigen Unternehmen verpflichtend, unter Verwendung des Standards Peppol BIS Billing 3.0 / EN 16931.', '["Verbinden Sie sich über einen zertifizierten Peppol Access Point (oder bestätigen Sie, dass Ihr Anbieter dies ist)","Stellen Sie Peppol BIS Billing 3.0 UBL-Rechnungen für alle inländischen B2B-Verkäufe aus und empfangen Sie sie","PDF- und Papierrechnungen sind nicht mehr zulässig — nur strukturiertes Format"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('be-penalty', 'de', 'Toleranzfrist endet — Sanktionen werden durchgesetzt', 'Die dreimonatige administrative Toleranzfrist endete; nun gilt ein progressives Sanktionssystem (1.500 € / 3.000 € / 5.000 €) bei nicht konformer Rechnungsstellung.', '["Beheben Sie ausstehende Lücken beim Peppol-Onboarding umgehend — Bußgelder gelten pro Verstoß","Prüfen Sie kürzlich ausgestellte Rechnungen auf Einhaltung des strukturierten Formats"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('be-ereport', 'de', 'Nahezu-Echtzeit-Meldung (5-Corner-Peppol-Modell)', 'Belgien plant die Einführung einer digitalen Umsatzsteuermeldung nahezu in Echtzeit über ein Fünf-Ecken-Peppol-Modell, das Rechnungsdaten automatisch an die Steuerbehörde meldet.', '["Beginnen Sie mit Ihrem Access-Point-Anbieter, die Fähigkeit zur Fünf-Ecken-Peppol-Meldung zu planen","Bestätigen Sie näher am Termin, dass dies weiterhin im Zeitplan liegt — die endgültigen Durchführungsbestimmungen stehen noch aus"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('de-receive', 'de', 'Verpflichtender Empfang strukturierter E-Rechnungen', 'Alle deutschen Unternehmen, unabhängig von ihrer Größe, müssen in der Lage sein, EN-16931-konforme strukturierte E-Rechnungen (XRechnung oder ZUGFeRD) für inländische B2B-Transaktionen zu empfangen.', '["Bestätigen Sie, dass Ihr Kreditorenprozess XRechnung-XML oder ZUGFeRD-Hybrid-PDFs akzeptieren kann","Ein E-Mail-Postfach mit Fähigkeit zum Empfang strukturierter Rechnungen erfüllt derzeit die Mindestanforderung"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('de-issue-large', 'de', 'Ausstellungspflicht — Unternehmen mit Umsatz über 800.000 €', 'Unternehmen mit einem Vorjahresumsatz über 800.000 € müssen strukturierte E-Rechnungen für inländische B2B-Transaktionen ausstellen; reine PDF-Rechnungen erfüllen für diese Gruppe nicht mehr die Anforderungen.', '["Bestätigen Sie, dass Ihr ERP XRechnung- oder ZUGFeRD-2.1+-Ausgaben erzeugen kann","Bestehende EDI-Vereinbarungen müssen bis Ende 2027 EN-16931-konform werden oder umgestellt werden"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('de-issue-all', 'de', 'Ausstellungspflicht — alle inländischen B2B-Unternehmen', 'Die Ausstellungspflicht gilt nun unabhängig vom Umsatz für jedes inländische B2B-Unternehmen und schließt Deutschlands stufenweise Einführung im Rahmen des Wachstumschancengesetzes ab.', '["Schließen Sie die Umstellung für alle verbleibenden inländischen B2B-Rechnungsprozesse ab","Nach diesem Datum gelten keine weiteren Übergangsregelungen"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fr-receive', 'de', 'Empfangspflicht + Ausstellungspflicht für große und mittlere Unternehmen', 'Alle umsatzsteuerpflichtigen Unternehmen in Frankreich müssen E-Rechnungen empfangen können; große und mittlere Unternehmen müssen sie zudem über das öffentliche Portal (PPF) oder eine akkreditierte Plattform (PA, ehemals PDP) ausstellen.', '["Registrieren Sie den Verzeichniseintrag Ihres Unternehmens beim PPF (Portail Public de Facturation)","Wählen Sie eine akkreditierte Plateforme Agréée oder nutzen Sie das kostenlose öffentliche Portal","Richten Sie E-Reporting für B2C- und grenzüberschreitende Transaktionen neben dem E-Invoicing ein"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fr-issue-all', 'de', 'Ausstellungspflicht gilt nun für alle verbleibenden Unternehmen', 'Klein- und Kleinstunternehmen, einschließlich Selbstständige, müssen E-Rechnungen ausstellen und schließen damit Frankreichs stufenweise B2B-E-Invoicing- und E-Reporting-Reform ab.', '["Schließen Sie die Rechnungssoftware oder PA-Integration rechtzeitig vor der Frist ab","Bestätigen Sie, dass Ihre Software Factur-X-, UBL- oder CII-Format unterstützt"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pl-large', 'de', 'KSeF verpflichtend — Großsteuerzahler (>200 Mio. PLN)', 'Großsteuerzahler mit einem Umsatz über 200 Millionen Zloty waren die erste Gruppe, die B2B-Rechnungen über die Clearing-Plattform Krajowy System e-Faktur (KSeF) ausstellen musste.', '["Integrieren Sie sich über die API mit KSeF unter Verwendung des XML-Schemas FA(3)","Richten Sie KSeF-Berechtigungen für Mitarbeiter und externe Aussteller ein"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pl-all', 'de', 'KSeF verpflichtend — alle übrigen umsatzsteuerpflichtigen Unternehmen', 'Die KSeF-Pflicht wurde auf alle verbleibenden umsatzsteuerpflichtigen Unternehmen in Polen (mit Ausnahme von Kleinstunternehmern) ausgeweitet; eine Rechnung ist erst rechtsverbindlich, nachdem KSeF sie freigegeben hat.', '["Bestätigen Sie, dass Ihr Rechnungssystem gültige strukturierte FA(3)-Rechnungen erzeugt","Korrekturnotizen (noty korygujące) sind nicht mehr gültig — nutzen Sie stattdessen den strukturierten Korrekturprozess von KSeF","Fügen Sie ab Inkrafttreten dieser Anforderung (1. August 2026) die KSeF-Rechnungsnummer den Überweisungsreferenzen hinzu"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pl-micro', 'de', 'KSeF verpflichtend — Kleinstunternehmer; Sanktionen beginnen', 'Kleinstunternehmer treten der KSeF-Pflicht bei, und die Übergangsfrist für finanzielle Sanktionen (bis zu 100 % der Rechnungs-Umsatzsteuer bei Nichteinhaltung) endet für alle.', '["Kleinstunternehmen: Bestätigen Sie, dass die KSeF-Integration weit vor diesem Datum aktiv ist","Alle Unternehmen: Beheben Sie verbleibende Compliance-Lücken, bevor Sanktionen greifen"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('it-sdi', 'de', 'Verpflichtendes B2B-/B2C-E-Invoicing über SDI (seit 2019 in Kraft)', 'Italien war der erste EU-Mitgliedstaat, der ein Clearing-Modell für E-Invoicing für praktisch alle inländischen Transaktionen — B2B, B2C und B2G — über das Sistema di Interscambio (SDI) im FatturaPA-XML-Format vorschrieb.', '["Bestätigen Sie, dass Ihr FatturaPA-Erzeugungs- und SDI-Übertragungskanal (PEC, FTP oder Webservice) weiterhin aktiv ist","Beobachten Sie Änderungen zur Angleichung an EN 16931/ViDA vor der Verlängerung der SDI-Ausnahmeregelung Italiens (bis 2027) und der EU-weiten Harmonisierungsfrist 2035"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sa-wave23', 'de', 'ZATCA Fatoora — Welle 23 (Umsatz > 750.000 SAR)', 'Unternehmen mit umsatzsteuerpflichtigem Umsatz über 750.000 SAR in 2022, 2023 oder 2024 mussten die Phase-2-Integration mit der Fatoora-Plattform für die Echtzeit-Freigabe abschließen.', '["Bestätigen Sie die direkte Benachrichtigungs- und Integrationsfrist der ZATCA für Ihr Unternehmen","Integrieren Sie Ihr Rechnungssystem mit der Fatoora-API für Echtzeit-B2B-/B2G-Freigabe","Stellen Sie sicher, dass Rechnungen eine UUID, einen QR-Code und einen kryptografischen Stempel enthalten"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sa-wave24', 'de', 'ZATCA Fatoora — Welle 24 (Umsatz > 375.000 SAR)', 'Die Schwelle sank auf 375.000 SAR — was praktisch der verpflichtenden Umsatzsteuer-Registrierungsschwelle entspricht und nahezu jedes umsatzsteuerpflichtige Unternehmen in die Phase-2-Freigabe einbezieht.', '["Gehen Sie davon aus, dass Sie betroffen sind, wenn Sie umsatzsteuerpflichtig sind; die ZATCA benachrichtigt betroffene Steuerzahler etwa sechs Monate im Voraus","Stellen Sie Standardrechnungen (Freigabe, abzugsfähige Vorsteuer) für B2B/B2G und vereinfachte Rechnungen für B2C aus, gemeldet innerhalb von 24 Stunden"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('my-phase4', 'de', 'MyInvois Phase 4 — Umsatz RM1–5 Mio.', 'Unternehmen mit einem Jahresumsatz zwischen RM1 Million und RM5 Millionen traten der Pflicht bei, mit einer bis zum 31. Dezember 2027 verlängerten Kulanzfrist (keine Sanktionen bei Übermittlungsfehlern).', '["Registrieren Sie sich für den Zugang zum MyInvois-Portal oder zur API bei der LHDN","Bestimmen Sie Ihre Phase anhand Ihres geprüften Jahresabschlusses 2022 oder der ersten verfügbaren Steuererklärung","Einzelne E-Rechnungen sind ab RM10.000 verpflichtend — konsolidierte Rechnungsstellung ist für diese Beträge nicht mehr zulässig"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('my-related', 'de', 'Verbundene/Tochterunternehmen von Gruppen mit RM1 Mio.+', 'Unternehmen mit einem Umsatz unter RM1 Million, die Tochter- oder verbundene Unternehmen einer Gruppe mit RM1 Million oder mehr sind, müssen dennoch die Vorgaben erfüllen, unabhängig vom eigenen Umsatz.', '["Prüfen Sie die Gruppenstruktur — der Status als verbundenes Unternehmen kann die Pflicht auch für kleine Einheiten auslösen","Registrieren und testen Sie die MyInvois-Integration rechtzeitig vor der Frist"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('in-threshold', 'de', 'GST-E-Invoicing verpflichtend ab einem Umsatz von ₹5 Crore (seit August 2023 in Kraft)', 'Jedes GST-registrierte Unternehmen mit einem aggregierten Jahresumsatz (AATO) über ₹5 Crore in einem Geschäftsjahr seit 2017–18 muss E-Rechnungen mit gültiger IRN für B2B- und Exporttransaktionen erstellen.', '["Bestätigen Sie den aggregierten Umsatz über alle GSTINs unter Ihrer PAN — die Schwelle von ₹5 Crore muss nur einmal überschritten werden","Registrieren Sie sich bei einem Invoice Registration Portal (IRP) — einvoice1.gst.gov.in des NIC oder einem autorisierten privaten IRP","Achten Sie auf eine mögliche Absenkung der Schwelle auf ₹2 Crore, die diskutiert, aber noch nicht bekanntgegeben wurde"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('in-30day', 'de', '30-Tage-Fenster für IRN-Meldung (AATO ≥ ₹10 Crore)', 'Rechnungen, Gutschriften und Lastschriften, die älter als 30 Tage sind, können nicht mehr zur IRN-Erstellung an das IRP gemeldet werden — sie werden für Steuerzahler mit AATO von ₹10 Crore oder mehr unmittelbar abgelehnt.', '["Integrieren Sie das 30-Tage-Meldefenster in Ihren Kreditoren-/Debitorenprozess","Aktivieren Sie die Multi-Faktor-Authentifizierung im GST-Portal — verpflichtend seit April 2025"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-fields', 'de', 'CBS/IBS-Felder auf NF-e/NFC-e/NFS-e erforderlich (Testsätze)', 'Mit Beginn der brasilianischen Doppel-Mehrwertsteuerreform müssen elektronische Steuerdokumente die neuen CBS- und IBS-Felder mit Testsätzen (0,9 % / 0,1 %) enthalten — noch ohne finanzielle Auswirkung, aber die rechtliche Pflicht zur Angabe der Daten gilt bereits.', '["Aktualisieren Sie die Rechnungslayouts auf die Technische Note 2025.002-RTC (neueste Version)","Testen Sie in der Homologationsumgebung der SEFAZ vor dem Go-Live","Steuerzahler unter Simples Nacional / MEI haben einen verlängerten Zeitplan bis 2027"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-validate', 'de', 'Validierung der CBS/IBS-Felder beginnt — Ablehnungsrisiko', 'Autorisierungssysteme beginnen mit einer strengen Validierung der CBS/IBS-Felder; Rechnungen mit fehlenden oder inkonsistenten Daten laufen Gefahr, automatisch abgelehnt zu werden.', '["Prüfen Sie die Rechnungsausgabe auf vollständige, konsistente CBS-/IBS-/IS-Datengruppen","Beheben Sie Ablehnungen zügig — blockierte Rechnungen stoppen den Warenverkehr"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-mandatory', 'de', 'Volle gesetzliche Meldepflicht für das allgemeine Steuerregime', 'Gemäß Technischer Note 2025.002-RTC v1.40 müssen Steuerzahler des allgemeinen Steuerregimes IBS- und CBS-Gruppen in NF-e und NFC-e mit voller Rechtswirkung melden.', '["Bestätigen Sie, dass Ihr ERP-/E-Invoicing-Anbieter die erforderlichen Schema-Updates abgeschlossen hat","Gleichen Sie gemeldete CBS-/IBS-Daten mit Ihren Buchhaltungsunterlagen vor der vollständigen Durchsetzung ab"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-verifactu-corp', 'de', 'VeriFactu-zertifizierte Rechnungssoftware — körperschaftsteuerpflichtige Unternehmen', 'Unternehmen, die der Körperschaftsteuer unterliegen, müssen VeriFactu-zertifizierte Rechnungssoftware (RRSIF) verwenden, die Integrität, Nachvollziehbarkeit und Unveränderlichkeit der an die Agencia Tributaria (AEAT) übermittelten Rechnungsdaten gewährleistet.', '["Bestätigen Sie, dass Ihre Rechnungssoftware VeriFactu-zertifiziert ist und die erforderliche Hash-Kette und den QR-Code erzeugt","Dies ist eine eigenständige Pflicht, unabhängig vom weiter unten beschriebenen breiteren Crea-y-Crece-B2B-E-Invoicing-Mandat"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-verifactu-rest', 'de', 'VeriFactu verpflichtend — alle übrigen Steuerzahler', 'Die VeriFactu-Pflicht gilt nun für alle übrigen Steuerzahler, die zur Führung von Rechnungsdaten verpflichtet sind, einschließlich Selbstständiger und anderer der Einkommensteuer unterliegender Berufsgruppen.', '["Selbstständige/Freiberufler: Stellen Sie sicher, dass zertifizierte Rechnungssoftware weit vor diesem Datum vorhanden ist","Unternehmen, die bereits das Echtzeit-Meldesystem SII nutzen, sind von VeriFactu befreit"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-b2b-large', 'de', 'Crea-y-Crece-B2B-E-Invoicing — Großunternehmen (Umsatz >8 Mio. €)', 'Strukturiertes B2B-E-Invoicing wird für Großunternehmen im Rahmen des Crea-y-Crece-Gesetzes verpflichtend, ausgetauscht über private Plattformen (mit verpflichtender Kopie an die staatliche Plattform) oder die kostenlose öffentliche Lösung (SPFE), parallel zu VeriFactu.', '["Wählen Sie eine private E-Invoicing-Plattform (muss eine Kopie an die SPFE weiterleiten) oder nutzen Sie die öffentliche Plattform direkt","Bestätigen Sie EN-16931-konforme Formate (UBL, Facturae, CII)","Melden Sie den Rechnungsstatus — angenommen, abgelehnt oder bezahlt — der AEAT innerhalb von 4 Kalendertagen"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-b2b-all', 'de', 'Crea-y-Crece-B2B-E-Invoicing — alle verbleibenden Unternehmen', 'Die B2B-E-Invoicing-Pflicht gilt nun auch für KMU, Einzelunternehmer und alle übrigen umsatzsteuerpflichtigen Unternehmen und schließt Spaniens zweigleisige E-Invoicing-Reform ab.', '["Finalisieren Sie die Plattformwahl und Integration rechtzeitig vor der Frist","Die endgültige Ministerialverordnung stand Mitte 2026 noch aus — bestätigen Sie dieses Datum näher am Zeitpunkt"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uk-mandate', 'de', 'Verpflichtendes E-Invoicing für alle umsatzsteuerpflichtigen Rechnungen (B2B und B2G)', 'Im Haushalt 2025 bestätigt: Alle umsatzsteuerpflichtigen Unternehmen müssen strukturierte E-Rechnungen für B2B- und B2G-Transaktionen ausstellen und empfangen, unter Verwendung eines dezentralen Vier-Ecken-Peppol-Modells. Eine Echtzeitmeldung an die HMRC ist nicht Teil dieser ersten Vorgabe.', '["Bestätigen Sie, dass Ihre Buchhaltungssoftware einen Weg zum Peppol-basierten E-Invoicing bietet","Achten Sie auf die vollständige Umsetzungs-Roadmap und technische Standards, die für den Haushalt 2026 erwartet werden","Unternehmen in Nordirland: Beachten Sie eine mögliche frühere, zusätzliche EU-angeglichene Pflicht für den Warenhandel ab Juli 2030"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ro-established', 'de', 'RO-e-Factura-Clearing-Modell verpflichtend für B2B/B2G (seit Juli 2024 in Kraft)', 'Rumänien betreibt ein zentralisiertes Clearing-Modell (CTC): B2B- und B2G-Rechnungen müssen von der ANAF über RO e-Factura validiert und digital versiegelt werden, bevor sie Rechtswirkung entfalten. Die B2C-Meldung folgte ab Januar 2025.', '["Bestätigen Sie die Registrierung bei RO e-Factura und die Erstellung RO_CIUS-konformer XML-Rechnungen","Die Übermittlungsfrist beträgt 5 Werktage ab Ausstellung (verkürzt von 5 Kalendertagen im Januar 2026)"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ro-sme', 'de', 'Volle Durchsetzung erweitert sich auf Kleinunternehmen (Umsatz <500.000 €)', 'Nach einer bestätigten Verzögerung unterliegen Kleinunternehmen mit einem Umsatz unter 500.000 € nun in vollem Umfang der e-Factura-Durchsetzung und den Sanktionen, gleichrangig mit größeren Unternehmen.', '["Standardisieren Sie Kundenadressen und Länder-/ISO-Codes rechtzeitig vor der Frist","Bestätigen Sie, dass Ihr Rechnungstool die 5-Werktage-Übermittlungsregel anwendet"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uae-pilot', 'de', 'Freiwillige Pilotphase für E-Invoicing beginnt', 'Die freiwillige Teilnahme wurde vor der Pflicht eröffnet, sodass Unternehmen die Konnektivität mit einem Accredited Service Provider (ASP) und das PINT-AE-Rechnungsformat risikofrei testen können, bevor Sanktionen greifen.', '["Erwägen Sie die Teilnahme am freiwilligen Pilotprogramm, um ASP-Integrationsprobleme vor der Pflichtphase zu lösen","Verfolgen Sie Aktualisierungen der technischen Leitlinien der Federal Tax Authority (FTA)"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uae-asp', 'de', 'Frist zur ASP-Benennung — Unternehmen mit Umsatz ≥ 50 Mio. AED', 'Unternehmen mit einem Umsatz von 50 Millionen AED oder mehr müssen vor dem Go-Live im Januar 2027 einen Accredited Service Provider (ASP) benannt haben (Frist verlängert vom 31. Juli 2026).', '["Wählen und beauftragen Sie einen von der FTA akkreditierten Accredited Service Provider","Beginnen Sie die PINT-AE-(UBL-2.1-)Integrationstests mit Ihrem ASP"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uae-phase1', 'de', 'Verpflichtender Go-Live Phase 1 — Umsatz ≥ 50 Mio. AED', 'Strukturiertes E-Invoicing wird für Großunternehmen verpflichtend, übermittelt über einen ASP im Peppol-Netzwerk im PINT-AE-Format, mit einer Echtzeit-Kopie an die FTA.', '["Schließen Sie die ASP-Integration und End-to-End-Tests vor dem Go-Live ab","Stellen Sie sicher, dass Rechnungen alle von der FTA geforderten Datenfelder enthalten — PDF und Papier sind nicht mehr zulässig"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uae-phase2', 'de', 'Die Pflicht erweitert sich auf alle übrigen umsatzsteuerpflichtigen Unternehmen', 'Die E-Invoicing-Pflicht erweitert sich auf alle verbleibenden umsatzsteuerpflichtigen Unternehmen für B2B-/B2G-Transaktionen, mit spezifischen G2B-/B2G-Pflichten ab Oktober 2027.', '["Bestätigen Sie den Umsatzsteuer-Registrierungsstatus und benennen Sie einen ASP rechtzeitig vor diesem Datum","Konzerninterne Transaktionen innerhalb einer einzelnen VAE-Umsatzsteuergruppe haben eine verlängerte Übergangsfrist bis zum 1. Januar 2029"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('mx-cfdi', 'de', 'Verpflichtendes CFDI-Clearing-Modell (aktuelle Version CFDI 4.0)', 'Mexiko betreibt eines der ausgereiftesten E-Invoicing-Clearing-Systeme der Welt: Jede Rechnung muss von einem autorisierten PAC validiert und digital gestempelt (timbrado) werden, bevor sie im CFDI-4.0-XML-Format rechtsgültig ist.', '["Stellen Sie die PAC-Konnektivität und die aktuelle Feldzuordnung nach CFDI 4.0 (Anexo 20) sicher — RFC/Name/Steuerregime des Empfängers müssen exakt mit den SAT-Daten übereinstimmen","Fügen Sie erforderliche Complementos bei Bedarf hinzu (Carta Porte für Warentransport, Pagos für Ratenzahlungen, Comercio Exterior für Exporte)","Bewahren Sie XML-Rechnungen und PAC-Bestätigungen mindestens 5 Jahre lang auf"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('mx-reform', 'de', 'Steuerreform 2026 — strengere Echtheitsanforderungen und Durchsetzung', 'Eine seit Januar 2026 geltende Steuerreform stärkte die Durchsetzungsbefugnisse der SAT und führte strengere Echtheitsprüfungen sowie strafrechtliche Haftung für gefälschte oder vorgetäuschte CFDIs ein.', '["Bewahren Sie Nachweise zur Echtheit von Transaktionen auf — Verträge, Lieferbelege, Zahlungsnachweise —, da die SAT diese innerhalb von 5 Werktagen anfordern kann","Überprüfen Sie CFDI-Verteidigungsunterlagen und Stornierungsverfahren angesichts der neuen strafrechtlichen Haftungsbestimmungen"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-ncereceive', 'de', 'Bundesbehörden müssen Peppol-E-Rechnungen empfangen können (seit Juli 2022 in Kraft)', 'Alle Non-Corporate Commonwealth Entities (Bundesbehörden) müssen seit dem 1. Juli 2022 Peppol-E-Rechnungen empfangen können. Es besteht keine allgemeine B2B-Pflicht, aber die staatliche Akzeptanz nimmt weiter zu.', '["Lieferanten von Bundesbehörden: Verbinden Sie sich über einen von der ATO akkreditierten Peppol Access Point","Über Peppol übermittelte Rechnungen können innerhalb von 5 statt der üblichen 20 Tage bezahlt werden"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-30pct', 'de', '30 % der Rechnungen von Bundesbehörden müssen über Peppol verarbeitet werden', 'Non-Corporate Commonwealth Entities müssen mindestens 30 % der erhaltenen Lieferantenrechnungen über das Peppol-Netzwerk abwickeln, auf dem Weg zur vollständigen Automatisierung bis Dezember 2026.', '["Wenn Sie australische Bundesbehörden beliefern, bestätigen Sie, dass Ihre Rechnungsstellung Peppol-fähig ist","Verwenden Sie das Format PINT A-NZ — der einzige unterstützte Standard seit dem 15. Mai 2025"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-automate', 'de', 'Bundesbehörden müssen Versand und Verarbeitung von E-Rechnungen automatisieren', 'Non-Corporate Commonwealth Entities müssen empfangene E-Rechnungen automatisch verarbeiten und E-Rechnungen versenden können, mit vierteljährlicher Fortschrittsberichterstattung an die Australian Peppol Authority.', '["Bestätigen Sie, dass Ihre E-Invoicing-Einrichtung eine vollständig automatisierte, berührungslose Verarbeitung unterstützt","Öffentliche Lieferanten sollten mit schnelleren Zahlungszyklen rechnen, sobald die Automatisierung greift"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nz-central', 'de', 'Zentrale Regierungsbehörden müssen E-Rechnungen empfangen können (seit März 2022 in Kraft)', 'Alle zentralen öffentlichen Behörden müssen seit März 2022 Peppol-E-Rechnungen empfangen können, verwaltet vom MBIE als neuseeländische Peppol-Autorität.', '["Lieferanten zentraler Behörden: Richten Sie die Peppol-Rechnungsfähigkeit über einen akkreditierten Access Point ein"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nz-2000', 'de', 'Behörden mit 2.000+ Rechnungen/Jahr müssen E-Rechnungen senden und empfangen', 'Regierungsbehörden, die jährlich mehr als 2.000 inländische Handelsrechnungen bearbeiten, müssen sowohl strukturierte E-Rechnungen senden als auch empfangen können und 95 % davon innerhalb von 5 Werktagen bezahlen.', '["Bestätigen Sie die Einhaltung des Formats PINT A-NZ — verpflichtend für staatliches E-Invoicing seit Mai 2025","Prüfen Sie, ob Ihr Regierungskunde innerhalb dieser Volumenschwelle liegt"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nz-largesupplier', 'de', 'Große Lieferanten (Umsatz >33 Mio. NZD) müssen E-Rechnungen an die Regierung übermitteln', 'Lieferanten mit einem Umsatz von über 33 Millionen NZD in jedem der letzten zwei Geschäftsjahre müssen E-Rechnungen über Peppol für inländische Handelsrechnungen an staatliche Käufer übermitteln.', '["Prüfen Sie, ob Ihr Umsatz die Schwelle von 33 Millionen NZD überschreitet","Integrieren Sie sich rechtzeitig vor der Frist mit einem Peppol Access Point"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-voluntary2025', 'de', 'GST InvoiceNow verpflichtend — neue freiwillige GST-Registrierte (innerhalb von 6 Monaten nach Gründung)', 'Die erste verpflichtende Phase von GST InvoiceNow verlangte von Unternehmen, die sich innerhalb von sechs Monaten nach Gründung freiwillig für die GST registrierten, Rechnungsdaten über das Peppol-basierte InvoiceNow-Netzwerk an die IRAS zu übermitteln.', '["Neue qualifizierte GST-Registrierte: Richten Sie zum Zeitpunkt der Registrierung eine InvoiceNow-Ready-Lösung und eine Peppol-ID ein"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-allvoluntary', 'de', 'Die Pflicht erweitert sich auf alle neuen freiwilligen GST-Registrierten', 'Alle neuen freiwilligen GST-Registrierten müssen unabhängig vom Gründungsdatum oder der Unternehmensstruktur InvoiceNow als Voraussetzung für die GST-Registrierung übernehmen.', '["Berücksichtigen Sie ab diesem Datum die InvoiceNow-Einrichtung in Ihrem GST-Registrierungsantrag","Nutzen Sie den Implementierungsdatum-Rechner der IRAS, falls unklar ist, welche Phase für Sie gilt"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-existing2028', 'de', 'Stufenweiser Rollout beginnt für bestehende GST-registrierte Unternehmen', 'Bestehende GST-registrierte Unternehmen werden nach einem stufenweisen Zeitplan in GST InvoiceNow einbezogen, der 2031 zur vollständigen Einführung führt. Die IRAS wird betroffene Unternehmen im Jahr 2026 über ihr spezifisches Datum informieren.', '["Nutzen Sie den GST-InvoiceNow-Implementierungsdatum-Rechner der IRAS, um Ihr geltendes Datum zu ermitteln","Achten Sie auf die direkte Benachrichtigung durch die IRAS (voraussichtlich Mitte 2026)"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-full2031', 'de', 'Vollständige Einführung — alle GST-registrierten Unternehmen', 'Bis zu diesem Datum muss jedes GST-registrierte Unternehmen in Singapur, einschließlich großer multinationaler Konzerne, Rechnungsdaten über InvoiceNow übermitteln.', '["Planen Sie die Integration weit im Voraus — übergangsweise stehen staatliche Zuschüsse zur Unterstützung der Einführung zur Verfügung"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sk-voluntary', 'de', 'Freiwillige Übergangsphase für E-Invoicing/E-Reporting beginnt', 'Unternehmen können sich freiwillig registrieren, um strukturiertes E-Invoicing und Meldewesen vor der Pflicht im Januar 2027 zu testen, unter Verwendung eines dezentralen, Peppol-basierten "5-Corner"-Modells.', '["Registrieren Sie sich für die freiwillige Teilnahme bei der Finanzverwaltung, um Integrationen frühzeitig zu testen","Bestätigen Sie, dass Ihre Buchhaltungssoftware Peppol-BIS-3.0-UBL-XML erzeugen kann"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sk-mandate', 'de', 'Verpflichtendes inländisches B2B-/B2G-E-Invoicing und Nahezu-Echtzeit-Meldung', 'Strukturiertes E-Invoicing und Echtzeitmeldung werden für inländische B2B- und B2G-Transaktionen zwischen slowakischen Umsatzsteuerpflichtigen verpflichtend, unter Verwendung zertifizierter "Digital Postman"-Access-Points in einem Peppol-basierten Netzwerk.', '["Wählen Sie einen zugelassenen Digital-Postman-Anbieter (zertifizierter Access Point)","Ab 2027 können Vorsteuerabzüge bei nicht konformen eingehenden Rechnungen nicht mehr geltend gemacht werden","Hinweis: Grenzüberschreitendes E-Invoicing folgt später, gemäß dem EU-ViDA-Zeitplan ab Juli 2030"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pe-established', 'de', 'E-Invoicing (CPE) verpflichtend für alle Steuerzahler (seit Juni 2022 in Kraft)', 'Peru betreibt eines der ausgereiftesten E-Invoicing-Systeme Lateinamerikas. Elektronische Zahlungsbelege (CPE) müssen im UBL-2.1-XML-Format erstellt, digital signiert und von der SUNAT oder einem autorisierten Electronic Services Operator (OSE) validiert werden, bevor sie rechtsgültig sind.', '["Verwenden Sie einen zugelassenen Electronic Service Provider (PSE) zur Erstellung und Signierung von CPEs","Übermitteln Sie E-Rechnungen innerhalb von 3 Kalendertagen nach Ausstellung an die SUNAT","Bewahren Sie XML-Rechnungen und CDR-Empfangsbestätigungen mindestens 5 Jahre lang auf"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cl-established', 'de', 'Elektronische Steuerdokumente (DTE) für alle Unternehmen verpflichtend (seit 2018 in Kraft)', 'Alle chilenischen Unternehmen müssen elektronische Steuerdokumente (Documentos Tributarios Electrónicos, DTE) ausstellen — einschließlich Facturas (B2B) und Boletas (B2C) —, validiert vom Servicio de Impuestos Internos (SII).', '["Bestätigen Sie, dass Ihr DTE-Ausstellungssystem autorisiert und mit dem SII verbunden ist","Bei Verkäufen über 135 UF muss die elektronische Boleta den Käufer per RUT und Namen identifizieren"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cl-digital-delivery', 'de', 'Digitale Zustellung der elektronischen Boleta erforderlich, wenn kein Drucker verfügbar ist', 'Unternehmen ohne Druckmöglichkeit müssen die elektronische Boleta digital zustellen — per E-Mail, SMS, WhatsApp, QR-Code oder einem anderen gleichwertigen elektronischen Kanal — statt die Zustellung ganz auszulassen.', '["Falls Ihnen ein Kassendrucker fehlt, richten Sie jetzt einen elektronischen Zustellkanal ein (E-Mail/SMS/QR)","Unternehmen mit Druckern müssen die gedruckte Darstellung im Allgemeinen weiterhin zustellen"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ie-phase1', 'de', 'Phase 1 — Großkonzerne müssen E-Rechnungen ausstellen; alle Unternehmen müssen empfangen können', 'Umsatzsteuerpflichtige Großkonzerne, die von der Large Corporates Division von Revenue verwaltet werden, müssen strukturierte E-Rechnungen ausstellen und einen Teil der Transaktionsdaten für inländische B2B-Verkäufe melden. Ab diesem Datum müssen alle Unternehmen technisch in der Lage sein, strukturierte E-Rechnungen zu empfangen.', '["Großkonzerne: Bewerten Sie jetzt die ERP-Bereitschaft für strukturierte EN-16931-Rechnungsstellung über Peppol","Alle Unternehmen: Bestätigen Sie, dass Ihre Systeme strukturierte E-Rechnungen empfangen können — PDFs werden von betroffenen Lieferanten nicht mehr akzeptiert"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ie-phase2', 'de', 'Phase 2 — die Pflicht erweitert sich auf alle umsatzsteuerpflichtigen Unternehmen im innergemeinschaftlichen Handel', 'Die inländische E-Invoicing- und Meldepflicht erweitert sich auf alle verbleibenden umsatzsteuerpflichtigen Unternehmen, die grenzüberschreitenden B2B-Handel innerhalb der EU betreiben, vor der vollständigen EU-ViDA-Konformität im Juli 2030.', '["Unternehmen mit grenzüberschreitendem Handel innerhalb der EU sollten mit der Planung der Peppol-Integration beginnen","Achten Sie auf detaillierte Leitlinien von Revenue, die deutlich vor jeder Phase erwartet werden"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('no-issue', 'de', 'Verpflichtende Ausstellung von B2B-E-Rechnungen (EHF 3.0 / Peppol BIS)', 'Nach Inkrafttreten der Änderungen des Buchführungsgesetzes müssen alle Unternehmen mit norwegischen Buchführungspflichten strukturierte E-Rechnungen (EHF-Format) an andere im ELMA-Verzeichnis registrierte Unternehmen ausstellen.', '["Registrieren Sie sich in ELMA (dem norwegischen Peppol-Empfängerverzeichnis), falls noch nicht gelistet","Bestätigen Sie, dass Ihre Rechnungssoftware EHF-3.0-/Peppol-BIS-Ausgaben unterstützt","PDF- und Papier-B2B-Rechnungen sind für betroffene Transaktionen nicht mehr gültig"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('no-receive', 'de', 'Verpflichtender Empfang von E-Rechnungen und vollständig digitale Buchführung', 'Die Pflicht erweitert sich auf den Empfang strukturierter E-Rechnungen und die Führung vollständig digitaler Buchhaltungsunterlagen und schließt Norwegens zweistufige Reform ab.', '["Planen Sie die Migration zu einem zugelassenen digitalen Buchführungssystem rechtzeitig vor diesem Datum","Bestätigen Sie, dass Kreditorensysteme EHF-/Peppol-Rechnungen automatisch empfangen und verarbeiten können"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('dk-established', 'de', 'Digitales Buchführungsgesetz durchgesetzt — mittlere/große Unternehmen (seit Juli 2024 in Kraft)', 'Mittlere und große Unternehmen, die Jahresberichte einreichen, müssen ein zertifiziertes digitales Buchführungssystem verwenden, das strukturierte E-Rechnungen (OIOUBL oder Peppol BIS 3.0) senden und empfangen sowie auf Anfrage SAF-T-Dateien erzeugen kann.', '["Bestätigen Sie, dass Ihr Buchführungssystem auf der zertifizierten Liste der dänischen Unternehmensbehörde steht, oder stellen Sie bei Nutzung eines individuellen Systems die Konformität selbst sicher","Führen Sie 5-jährige digitale Aufzeichnungen mit automatisierter externer Sicherung"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('dk-small', 'de', 'Kleinunternehmen (Umsatz >300.000 DKK) mit individuellen Systemen müssen die Vorgaben erfüllen', 'Kleinunternehmen und Einzelunternehmen, die in zwei aufeinanderfolgenden Jahren einen Umsatz von 300.000 DKK überschreiten und nicht registrierte ("individuelle") Buchhaltungssysteme verwenden, unterliegen nun vollständig den digitalen Anforderungen des Buchführungsgesetzes.', '["Prüfen Sie, ob Ihr Umsatz die Schwelle von 300.000 DKK in den letzten zwei Geschäftsjahren überschritten hat","Unternehmen mit registrierten/zertifizierten Systemen mussten die Vorgaben bereits seit Januar 2026 erfüllen"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('se-b2g', 'de', 'B2G-E-Invoicing für alle öffentlichen Stellen verpflichtend (seit 2019 in Kraft)', 'Alle Vergabestellen und öffentlichen Einrichtungen in Schweden müssen EN-16931-konforme E-Rechnungen empfangen können, wobei Peppol BIS Billing 3.0 das empfohlene (und zunehmend geforderte) Format ist, während Altformate wie Svefaktura ausgemustert werden.', '["Lieferanten schwedischer öffentlicher Stellen: Nutzen Sie nach Möglichkeit Peppol BIS Billing 3.0 — die Altformate SFTI/EDIFACT werden abgeschafft","Es besteht noch keine inländische B2B-Pflicht — siehe den folgenden Eintrag zur erwarteten EU-Angleichung"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('se-b2b-expected', 'de', 'Grenzüberschreitendes B2B-E-Invoicing unter EU-ViDA erwartet', 'Schweden hat noch keine inländische B2B-E-Invoicing-Pflicht gesetzlich verankert; Skatteverket, DIGG und Bolagsverket haben die Regierung gebeten, eine solche zu prüfen, doch die einzige feste Frist ist derzeit die EU-weite ViDA-Grenzüberschreitungspflicht.', '["Verfolgen Sie eine mögliche Ankündigung einer inländischen Pflicht — ein formeller Regierungsvorschlag steht noch aus","Grenzüberschreitend tätige Unternehmen sollten sich dennoch auf EN-16931-/Peppol-Bereitschaft vor der EU-weiten Frist 2030 vorbereiten"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cn-nationwide', 'de', 'Vollständig digitalisierte E-Rechnung (e-fapiao) landesweit eingeführt (seit Dezember 2024 in Kraft)', 'Die staatliche Steuerverwaltung (STA) schloss die landesweite Einführung vollständig digitalisierter elektronischer Rechnungen (e-fapiao) ab, die nun dieselbe Rechtsgültigkeit wie Papierrechnungen haben und die früheren Pilotphasen des Golden-Tax-Systems ablösen.', '["Richten Sie ein digitales Steuerkonto bei der STA ein, um e-fapiao auszustellen und zu empfangen","Bestätigen Sie, dass ERP-/Rechnungssysteme e-fapiao mit den vorgeschriebenen vereinfachten chinesischen Feldern und OFD-/XML-Darstellung erzeugen können","Bewahren Sie den STA-Rechnungscode, die digitale Signatur, den dynamischen QR-Code und den Freigabezeitstempel jeder Rechnung auf"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cn-paper-phaseout', 'de', 'Regionale Abschaffung von Papierrechnungen beschleunigt sich', 'Lokale Steuerbehörden in mehreren Regionen (z. B. Dalian, mit Wirkung zum 1. Juli 2026) haben begonnen, bestimmte steuerlich überwachte Papierrechnungsarten zugunsten von e-fapiao einzustellen, wobei im Jahr 2026 weitere Regionen folgen dürften.', '["Prüfen Sie die Ankündigungen Ihrer lokalen STA-Niederlassung zu den regions- und branchenspezifischen Abschaffungsterminen für Papierrechnungen","Vor dem regionalen Stichtag ausgestellte Rechnungen bleiben gültig, aber neue Papierausstellungen können ab diesem Datum blockiert werden"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('hr-b2b', 'de', 'Fiskalizacija 2.0 — verpflichtendes E-Invoicing und E-Reporting für umsatzsteuerpflichtige Unternehmen', 'Kroatiens "Fiskalisierung 2.0"-Reform machte strukturiertes E-Invoicing (Ausstellung und Empfang) sowie Echtzeit-E-Reporting für alle umsatzsteuerpflichtigen, in Kroatien ansässigen Steuerzahler verpflichtend, zusätzlich zur seit 2019 geltenden B2G-E-Invoicing-Pflicht.', '["Registrieren Sie eine AMS-Adresse und beauftragen Sie einen zertifizierten Informationsvermittler oder Access Point","Stellen Sie sicher, dass ERP-Systeme gültiges UBL-2.1-XML gemäß dem CIUS HR-FISK 2.0 erzeugen (einschließlich 6-stelliger KPD-Codes und OIBs)","Integrieren Sie den 5-Tage-Fiskalisierungsprozess auf Käuferseite sowie das monatliche E-Reporting bis zum 20.","Archivieren Sie originale XML-Rechnungen 11 Jahre lang"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('hr-nonvat', 'de', 'Die Pflicht erweitert sich auf nicht umsatzsteuerregistrierte Einrichtungen und öffentliche Stellen', 'Die Pflicht zur Ausstellung (nicht nur zum Empfang) strukturierter E-Rechnungen und E-Reporting-Daten erweitert sich auf nicht umsatzsteuerregistrierte Einrichtungen — kleine Unternehmen, Selbstständige und bestimmte öffentliche/haushaltsgebundene Stellen.', '["Nicht umsatzsteuerregistrierte Unternehmen und Einzelunternehmer: Bestätigen Sie die Fähigkeit zur E-Rechnungsausstellung rechtzeitig vor diesem Datum","Nicht umsatzsteuerregistrierte öffentliche Stellen sollten die Access-Point-Integration im Jahr 2026 abschließen"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('us-federal-b2g', 'de', 'Bundesbehörden müssen Rechnungen elektronisch verwalten (B2G, seit 2018 in Kraft)', 'Das Office of Management and Budget wies Bundesbehörden an, für geeignete Beschaffungen auf elektronische Rechnungsstellung umzustellen. Die meisten nutzen inzwischen die Invoice Processing Platform (IPP) des Finanzministeriums — es gibt jedoch kein einheitlich vorgeschriebenes Format und keine inländische B2B-Pflicht jeglicher Art.', '["Wenn Sie an Bundesbehörden verkaufen, bestätigen Sie, dass Sie auf der IPP oder dem von Ihrer Behörde vorgesehenen E-Invoicing-Kanal eingerichtet sind","Bewahren Sie elektronische Rechnungsunterlagen so auf, dass sie gemäß IRS-Leitlinien (Publikation 583) zugänglich, korrekt und lesbar bleiben"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('us-dbnalliance', 'de', 'DBNAlliance-B2B-E-Rechnungsaustauschnetzwerk aktiv (freiwillig, marktgetrieben)', 'Die Digital Business Networks Alliance (DBNAlliance) — eine gemeinnützige Organisation, die aus einem Pilotprojekt der Federal Reserve / Business Payments Coalition hervorging — betreibt nun ein Peppol-ähnliches Vier-Ecken-Netzwerk für den freiwilligen strukturierten B2B-E-Rechnungsaustausch in den USA und Kanada. Kein Bundes- oder Landesgesetz schreibt die Einführung vor.', '["Erwägen Sie den Anschluss über einen von DBNAlliance zertifizierten Dienstleister vor einer möglichen künftigen Pflicht","Falls Sie mit Partnern in Ländern handeln, die E-Invoicing bereits vorschreiben (EU, Mexiko, Brasilien usw.), stellen Sie sicher, dass Ihre Systeme weiterhin deren erforderliche Formate erzeugen können"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ca-federal-b2g', 'de', 'Alle Lieferanten der Bundesregierung müssen elektronisch fakturieren (B2G, seit 2022 in Kraft)', 'Seit April 2022 verlangt Public Services and Procurement Canada (PSPC) von Lieferanten, Rechnungen elektronisch über seine SAP-Ariba-basierte E-Beschaffungslösung einzureichen. Es besteht keine bundesweite B2B-E-Invoicing-Pflicht.', '["Wenn Sie die kanadische Regierung beliefern, registrieren Sie sich über CanadaBuys in SAP Ariba","Bewahren Sie elektronische Rechnungen gemäß den Aufbewahrungspflichten der CRA mindestens 6 Jahre lang auf"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ca-watch', 'de', 'CRA prüft eine mögliche B2B-E-Invoicing-Pflicht (keine Pflicht erlassen)', 'Die Canada Revenue Agency führte eine Stakeholder-Untersuchung zu einer möglichen inländischen B2B-E-Invoicing-Pflicht durch. Es folgten weder Gesetzgebung noch ein fester Zeitplan — die GST-/HST-Vorschriften bleiben formatneutral, und Papier-, PDF- und EDI-Rechnungen sind derzeit alle zulässig, sofern sie die erforderlichen Steuerangaben enthalten.', '["Heute ist über gute Aufbewahrungspraxis hinaus keine Maßnahme erforderlich","Verfolgen Sie künftige Ankündigungen der CRA / von Finance Canada, insbesondere da die Nutzung des DBNAlliance-Netzwerks in Kanada zunimmt"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-b2g-large', 'de', 'B2G-E-Rechnung für Großunternehmen verpflichtend (in Kraft seit Januar 2021)', 'Großunternehmen, die öffentliche Verwaltungsstellen beliefern, müssen strukturierte E-Rechnungen im nationalen Format CIUS-PT ausstellen (eine portugiesische Umsetzung von EN 16931, via UBL 2.1 oder CEFACT CII), übermittelt über die von eSPap betriebene FE-AP-Plattform oder einen anderen zugelassenen Kanal. Portugal hat keine allgemeine B2B- oder B2C-E-Invoicing-Vorgabe — diese Anforderung gilt speziell für die Belieferung des öffentlichen Sektors.', '["Bestätigen Sie, dass Ihr Rechnungssystem gültiges strukturiertes CIUS-PT-XML erzeugen kann, nicht nur eine PDF-Darstellung","Verbinden Sie sich mit FE-AP oder einem zugelassenen alternativen Kanal zur Übermittlung von Rechnungen an öffentliche Stellen"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-b2g-sme', 'de', 'B2G-Vorgabe erstreckt sich auf kleine, mittlere und Kleinstunternehmen', 'Die Anforderung strukturierter CIUS-PT-E-Rechnungen für Lieferanten des öffentlichen Sektors, die zuvor nur für Großunternehmen galt, erstreckt sich nun auf kleine, mittlere und Kleinstunternehmen. Unabhängig von Unternehmensgröße oder B2G-Status müssen zudem alle Rechnungen — Papier oder elektronisch — bereits mit AT-zertifizierter Software ausgestellt werden und einen ATCUD-Code, einen QR-Code sowie eine Hash-Kette zur Echtheitsprüfung tragen.', '["Wenn Sie eine portugiesische öffentliche Stelle beliefern und noch keine strukturierten CIUS-PT-Rechnungen ausstellen, ist dies bereits eine aktive Compliance-Lücke, keine zukünftige","Bestätigen Sie unabhängig von Ihrem B2G-Status, dass Ihre Rechnungssoftware auf der AT-zertifizierten Liste steht — die Nutzung nicht zertifizierter Software macht eine Rechnung unabhängig von ihrem Inhalt ungültig"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-qes', 'de', 'Qualifizierte Elektronische Signatur (QES) für PDF-Rechnungen erforderlich', 'PDF-Rechnungen in B2B- und B2C-Transaktionen benötigen eine Qualifizierte Elektronische Signatur eines EU-gelisteten qualifizierten Vertrauensdiensteanbieters, um weiterhin rechtsgültig zu sein — verschoben von einem ursprünglichen Datum 2026 über den Staatshaushalt 2026. Bis zum 31. Dezember 2026 bleiben von zertifizierter Software ausgestellte PDF-Rechnungen mit ATCUD und QR-Code auch ohne QES gültig. Diese Ebene gilt zusätzlich zu, nicht anstelle der bereits geltenden Anforderungen an zertifizierte Software/ATCUD/QR/SAF-T.', '["Identifizieren Sie einen EU-gelisteten qualifizierten Vertrauensdiensteanbieter für QES rechtzeitig vor der Frist 2027 — dies ist ein eigener Beschaffungsschritt, keine Softwareeinstellung","Gehen Sie nicht davon aus, dass die Einhaltung der bestehenden ATCUD-/QR-/Zertifizierungssoftware-Anforderungen dies bereits abdeckt — QES ist eine echte, zusätzliche Ebene speziell für PDF-Rechnungen"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fi-b2g', 'de', 'B2G-E-Rechnung verpflichtend (in Kraft seit April 2020)', 'Alle Lieferanten, die finnische Regierungsbehörden in Rechnung stellen, müssen E-Rechnungen senden, sofern nicht anders vereinbart — eines der ausgereiftesten B2G-Regime Europas, mit rund 99 % bereits elektronischer Rechnungen an öffentliche Auftraggeber. Finnland hat keine allgemeine B2B- oder B2C-E-Invoicing-Vorgabe: Die inländische B2B-E-Rechnungsstellung bleibt vollständig freiwillig, obwohl Unternehmen mit einem Umsatz über 10.000 € nach dem E-Invoicing-Gesetz 241/2019 einen gesetzlichen Anspruch haben, E-Rechnungen von ihren Lieferanten zu verlangen.', '["Wenn Sie eine finnische öffentliche Stelle beliefern, bestätigen Sie, dass Sie E-Rechnungen senden können — dies ist seit Jahren die Norm, keine neue Anforderung","Gehen Sie bei inländischem B2B nicht von einer gesetzlichen Vorgabe aus — prüfen Sie stattdessen die spezifischen vertraglichen Anforderungen Ihres Kunden"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fi-en-standard', 'de', 'Staat verlangt EN-16931-konforme E-Rechnungen (in Kraft seit April 2021)', 'Ab diesem Datum akzeptieren finnische Regierungsbehörden nur noch E-Rechnungen, die dem Europäischen Standard (EN 16931) entsprechen — nicht standardisierte Formate reichen für die B2G-Rechnungsstellung nicht mehr aus, obwohl die E-Rechnungsstellung selbst bereits seit einem Jahr verpflichtend war. Sowohl Finvoice 3.0 als auch TEAPPSXML 3.0 können EN-konforme Rechnungen erzeugen, doch die Konformität ist nicht automatisch — Unternehmen müssen prüfen, dass die Ausgabe ihrer Software den Standard tatsächlich erfüllt, statt es standardmäßig anzunehmen.', '["Bestätigen Sie, dass die Finvoice-3.0- oder TEAPPSXML-3.0-Ausgabe Ihrer Software tatsächlich EN-16931-konform ist, nicht nur oberflächlich ähnlich","Prüfen Sie im Verkkolaskuosoite-Verzeichnis, welcher E-Invoicing-Betreiber/welches Portal eine bestimmte Stelle im öffentlichen Sektor erreicht — es gibt keine einzige zentrale Plattform"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fi-vida', 'de', 'Innergemeinschaftliche B2B-E-Rechnung unter dem EU-ViDA-Rahmen verpflichtend', 'Finnland hat derzeit keine inländische B2B-E-Invoicing-Vorgabe, und keine ist vor dieser EU-weiten Frist bestätigt, unter der innergemeinschaftliche B2B-Transaktionen in jedem Mitgliedstaat strukturierte E-Rechnungen und digitale Meldungen erfordern. Die finnische Regierung hat signalisiert, dass sie Vorbereitungen um 2028 beginnen plant, und eine inländische Vorgabe könnte dieser EU-Frist eher folgen als vorausgehen — eine genuin andere Haltung als bei den meisten anderen EU-Ländern in diesem Tracker, die der EU-Untergrenze von 2030 deutlich vorauseilen.', '["Gehen Sie nicht davon aus, dass Finnland demselben inländischen Vorgaben-Zeitplan wie seine nordischen Nachbarn folgt — bislang wurde kein inländisches Vorgabendatum festgelegt","Prüfen Sie diese Seite regelmäßig erneut, statt das derzeitige Fehlen einer Vorgabe als dauerhaften Zustand zu behandeln — die Vorbereitungen für 2028 könnten einen konkreteren inländischen Zeitplan zutage fördern"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('lx-b2g', 'de', 'B2G-E-Invoicing-Pflicht vollständig in Kraft', 'Luxemburgs stufenweise Einführung der B2G-E-Rechnung ist abgeschlossen: Alle Wirtschaftsteilnehmer, einschließlich kleiner und neu gegründeter Unternehmen, müssen nun Peppol-BIS-Billing-3.0- / EN-16931-E-Rechnungen an luxemburgische öffentliche Stellen ausstellen.', '["Bestätigen Sie, dass Ihr Peppol Access Point (oder die manuelle Upload-Option von guichet.lu) für jeden von Ihnen belieferten öffentlichen Auftrag eingerichtet ist","Strukturierte EN-16931-Rechnungen sind für die gesamte öffentliche Beschaffung erforderlich — es gilt kein Schwellenwert"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('lx-b2b-receipt', 'de', 'Vorschlag: Empfang von B2B-E-Rechnungen wird verpflichtend', 'Nach dem vom luxemburgischen Regierungsrat am 17. Juli 2026 gebilligten Gesetzentwurf müssten alle Unternehmen in der Lage sein, strukturierte E-Rechnungen für inländische B2B-Transaktionen über ein Peppol-Vier-Ecken-Netzwerk zu empfangen — noch vor der Pflicht zur Ausstellung.', '["Verfolgen Sie den Gesetzentwurf im Parlament — es handelt sich noch um einen Entwurf, der noch nicht in Kraft ist","Bestätigen Sie, dass Ihr Rechnungs-/ERP-System bereits Peppol-BIS-Billing-3.0-Rechnungen empfangen kann"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('lx-b2b-issue-large', 'de', 'Vorschlag: Ausstellung von B2B-E-Rechnungen für große und mittlere Unternehmen', 'Große und mittlere Unternehmen müssten strukturierte inländische B2B-E-Rechnungen über Peppol nicht nur empfangen, sondern auch ausstellen — sechs Monate nachdem die Empfangspflicht für alle in Kraft getreten ist.', '["Größere Lieferanten: Beginnen Sie das Onboarding beim Peppol Access Point rechtzeitig vor diesem Termin","Bestätigen Sie Ihre aktuelle Einstufung nach Unternehmensgröße, da diese die geltende Frist bestimmt"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('lx-b2b-issue-all', 'de', 'Vorschlag: Ausstellung von B2B-E-Rechnungen wird allgemein verpflichtend', 'Die übrigen Unternehmen, einschließlich KMU, müssten strukturierte inländische B2B-E-Rechnungen ausstellen und damit die stufenweise Einführung abschließen, die im Zusammenhang mit den EU-Reformen zur Mehrwertsteuer im digitalen Zeitalter (ViDA) angekündigt wurde.', '["KMU: Dies ist die für Sie geltende Frist, 18 Monate nach Beginn der Empfangspflicht","Eine inländische Echtzeit-Umsatzsteuermeldung ist damit nicht geplant — Luxemburg bleibt beim Peppol-Interoperabilitätsmodell und führt kein Clearing-System ein"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-transpose', 'fr', 'ViDA — échéance de transposition de l''immatriculation unique à la TVA', 'Les États membres doivent transposer les dispositions relatives à l''immatriculation unique à la TVA (Single VAT Registration, SVR) de la directive ViDA dans leur droit national avant cette date, afin que le champ élargi du guichet unique (OSS)/guichet unique à l''importation (IOSS) et les clarifications associées puissent s''appliquer à partir du 1er janvier 2027. Cette échéance concerne spécifiquement le pilier SVR — elle est distincte des calendriers de transposition du pilier économie de plateformes de ViDA (2028) et de son pilier facturation électronique / obligations de déclaration numérique (2030), et leur est antérieure.', '["Si vous vendez des biens ou services B2C transfrontaliers au sein de l''UE, vérifiez que votre immatriculation OSS/IOSS couvre le champ élargi entrant en vigueur en janvier 2027","Cette échéance n''impose pas en elle-même la facturation électronique domestique — les États membres peuvent déjà introduire leurs propres obligations de facturation électronique de manière indépendante, en vertu des dérogations disponibles depuis l''entrée en vigueur de ViDA en avril 2025","Suivez le calendrier de transposition et de facturation électronique domestique de votre propre administration fiscale nationale séparément de cette échéance SVR à l''échelle de l''UE"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-platform-svr-2028', 'fr', 'ViDA — entrée en vigueur de l''économie de plateformes et de l''immatriculation unique à la TVA', 'Les plateformes numériques facilitant la location de courte durée et le transport routier de voyageurs deviennent le fournisseur présumé (deemed supplier) aux fins de la TVA lorsque le prestataire sous-jacent ne facture pas lui-même la TVA (par exemple, petites entreprises ou particuliers). Les réformes de l''immatriculation unique à la TVA entrent en vigueur dans toute l''UE, et un mécanisme d''autoliquidation domestique obligatoire s''applique lorsqu''un fournisseur n''est ni établi ni immatriculé à la TVA dans l''État membre de fourniture.', '["Si vous exploitez une plateforme concernée (location de courte durée ou transport routier de voyageurs), vérifiez vos obligations de collecte et de reversement de la TVA en tant que fournisseur présumé","Si vous fournissez des biens ou services dans un État membre où vous n''êtes pas immatriculé à la TVA, vérifiez si la nouvelle autoliquidation obligatoire s''applique désormais à vos opérations","Évaluez si le modèle élargi d''immatriculation unique à la TVA vous permet de consolider les immatriculations que vous détenez actuellement dans plusieurs États membres"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-drr', 'fr', 'ViDA — obligations de déclaration numérique transfrontalières', 'La facturation électronique structurée et les obligations de déclaration numérique (DRR) quasi en temps réel deviennent obligatoires dans toute l''UE pour les transactions B2B transfrontalières. L''état récapitulatif est supprimé et remplacé par le DRR.', '["Être en mesure d''émettre des factures électroniques conformes à EN 16931 dans les 10 jours suivant le fait générateur pour les ventes B2B intracommunautaires","Intégrez la déclaration quasi en temps réel dans votre chaîne de facturation avant la mise en service","Supprimez les processus liés à l''état récapitulatif une fois que le DRR les remplace"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-align', 'fr', 'ViDA — harmonisation des systèmes nationaux', 'Tous les systèmes nationaux de facturation électronique et de déclaration déjà existants (y compris des modèles de contrôle établis comme le SDI italien) doivent être alignés sur la norme harmonisée ViDA de l''UE.', '["Si vous opérez dans un pays disposant de son propre système de contrôle, vérifiez son plan d''alignement sur EN 16931/ViDA","Planifiez un modèle de déclaration unique pour tous les marchés de l''UE où vous opérez"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('be-mandate', 'fr', 'Facturation électronique B2B obligatoire via Peppol', 'La facturation électronique structurée est devenue obligatoire pour les transactions B2B nationales entre entreprises belges assujetties à la TVA, selon la norme Peppol BIS Billing 3.0 / EN 16931.', '["Connectez-vous via un Access Point Peppol certifié (ou vérifiez que votre prestataire en est un)","Émettez et recevez des factures UBL Peppol BIS Billing 3.0 pour toutes les ventes B2B nationales","Les factures PDF et papier ne sont plus valables — seul le format structuré est accepté"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('be-penalty', 'fr', 'Fin de la période de tolérance — sanctions appliquées', 'La période de tolérance administrative de trois mois a pris fin ; un régime de sanctions progressives (1 500 € / 3 000 € / 5 000 €) s''applique désormais à la facturation non conforme.', '["Résolvez immédiatement toute lacune d''intégration Peppol en suspens — des amendes s''appliquent par infraction","Vérifiez les factures récentes pour vous assurer de la conformité au format structuré"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('be-ereport', 'fr', 'Déclaration quasi en temps réel (modèle Peppol à 5 coins)', 'La Belgique prévoit d''introduire une déclaration numérique de TVA quasi en temps réel via un modèle Peppol à cinq coins, transmettant automatiquement les données de facturation à l''administration fiscale.', '["Commencez à définir la capacité de déclaration Peppol à cinq coins avec votre fournisseur d''Access Point","Vérifiez que ce calendrier reste d''actualité à l''approche de l''échéance — les règles d''application définitives sont encore en attente"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('de-receive', 'fr', 'Réception obligatoire de factures électroniques structurées', 'Toutes les entreprises allemandes, quelle que soit leur taille, doivent être en mesure de recevoir des factures électroniques structurées conformes à EN 16931 (XRechnung ou ZUGFeRD) pour les transactions B2B nationales.', '["Vérifiez que votre processus de comptes fournisseurs peut accepter les XML XRechnung ou les PDF hybrides ZUGFeRD","Une boîte de réception e-mail capable d''accepter des factures structurées répond actuellement à l''exigence minimale"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('de-issue-large', 'fr', 'Obligation d''émission — entreprises dont le chiffre d''affaires dépasse 800 000 €', 'Les entreprises dont le chiffre d''affaires de l''année précédente dépasse 800 000 € doivent émettre des factures électroniques structurées pour les transactions B2B nationales ; les factures uniquement en PDF ne sont plus acceptées pour ce groupe.', '["Vérifiez que votre ERP peut générer des sorties XRechnung ou ZUGFeRD 2.1+","Les accords EDI existants doivent devenir conformes à EN 16931 ou être remplacés d''ici fin 2027"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('de-issue-all', 'fr', 'Obligation d''émission — toutes les entreprises B2B nationales', 'L''obligation d''émission s''étend à toutes les entreprises B2B nationales, quel que soit leur chiffre d''affaires, achevant le déploiement par étapes de l''Allemagne dans le cadre de la loi sur les opportunités de croissance.', '["Achevez le déploiement pour tous les flux de facturation B2B nationaux restants","Aucune autre disposition transitoire ne s''appliquera après cette date"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fr-receive', 'fr', 'Obligation de réception + émission pour les grandes et moyennes entreprises', 'Toutes les entreprises assujetties à la TVA en France doivent pouvoir recevoir des factures électroniques ; les grandes et moyennes entreprises doivent également les émettre via le portail public (PPF) ou une plateforme agréée (PA, anciennement PDP).', '["Enregistrez l''entrée de votre annuaire d''entreprise auprès du PPF (Portail Public de Facturation)","Choisissez une Plateforme Agréée ou utilisez le portail public gratuit","Mettez en place l''e-reporting pour les transactions B2C et transfrontalières en parallèle de la facturation électronique"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fr-issue-all', 'fr', 'L''obligation d''émission s''étend à toutes les entreprises restantes', 'Les petites et micro-entreprises, y compris les indépendants, doivent émettre des factures électroniques, achevant la réforme française par étapes de facturation électronique et d''e-reporting B2B.', '["Finalisez le logiciel de facturation ou l''intégration avec la PA bien avant l''échéance","Vérifiez que votre logiciel prend en charge le format Factur-X, UBL ou CII"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pl-large', 'fr', 'KSeF obligatoire — grands contribuables (>200 M PLN)', 'Les grands contribuables dont le chiffre d''affaires dépasse 200 millions de zlotys ont été le premier groupe tenu d''émettre des factures B2B via la plateforme de contrôle Krajowy System e-Faktur (KSeF).', '["Intégrez-vous à KSeF via l''API en utilisant le schéma XML FA(3)","Configurez les autorisations KSeF pour le personnel et tout émetteur tiers"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pl-all', 'fr', 'KSeF obligatoire — toutes les autres entreprises assujetties à la TVA', 'L''obligation KSeF s''est étendue à toutes les entreprises assujetties à la TVA restantes en Pologne (à l''exception des micro-entrepreneurs) ; une facture n''a force légale qu''une fois validée par KSeF.', '["Vérifiez que votre système de facturation génère des factures structurées FA(3) valides","Les notes de correction (noty korygujące) ne sont plus valables — utilisez plutôt le processus de correction structuré de KSeF","Ajoutez le numéro de facture KSeF aux références de virement bancaire une fois cette exigence en vigueur (1er août 2026)"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pl-micro', 'fr', 'KSeF obligatoire — micro-entrepreneurs ; début des sanctions', 'Les micro-entrepreneurs rejoignent l''obligation KSeF, et la période de grâce sur les sanctions financières (jusqu''à 100 % de la TVA de la facture en cas de non-conformité) prend fin pour tous.', '["Micro-entreprises : vérifiez que l''intégration KSeF est active bien avant cette date","Toutes les entreprises : résolvez toute lacune de conformité persistante avant l''application des sanctions"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('it-sdi', 'fr', 'Facturation électronique B2B/B2C obligatoire via SDI (en vigueur depuis 2019)', 'L''Italie a été le premier État membre de l''UE à imposer un modèle de contrôle pour la facturation électronique sur la quasi-totalité des transactions nationales — B2B, B2C et B2G — via le Sistema di Interscambio (SDI), au format XML FatturaPA.', '["Vérifiez que votre canal de génération FatturaPA et de transmission au SDI (PEC, FTP ou service web) reste actif","Surveillez les évolutions liées à l''alignement EN 16931/ViDA avant le renouvellement de la dérogation SDI de l''Italie (jusqu''en 2027) et l''échéance d''harmonisation à l''échelle de l''UE en 2035"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sa-wave23', 'fr', 'ZATCA Fatoora — Vague 23 (chiffre d''affaires > 750 000 SAR)', 'Les entreprises dont le chiffre d''affaires imposable à la TVA dépassait 750 000 SAR en 2022, 2023 ou 2024 devaient achever l''intégration de la phase 2 avec la plateforme Fatoora pour le contrôle en temps réel.', '["Vérifiez le délai de notification et d''intégration direct de la ZATCA pour votre entité","Intégrez votre système de facturation à l''API Fatoora pour le contrôle B2B/B2G en temps réel","Assurez-vous que les factures comportent un UUID, un code QR et un cachet cryptographique"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sa-wave24', 'fr', 'ZATCA Fatoora — Vague 24 (chiffre d''affaires > 375 000 SAR)', 'Le seuil est passé à 375 000 SAR — correspondant en pratique au seuil obligatoire d''immatriculation à la TVA, intégrant ainsi la quasi-totalité des entreprises assujetties dans le contrôle de la phase 2.', '["Considérez que vous êtes concerné si vous êtes assujetti à la TVA ; la ZATCA notifie les contribuables concernés environ six mois à l''avance","Émettez des factures Standard (contrôle, TVA déductible) pour le B2B/B2G et des factures Simplifiées pour le B2C, déclarées dans les 24 heures"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('my-phase4', 'fr', 'MyInvois Phase 4 — chiffre d''affaires de 1 à 5 M RM', 'Les entreprises dont le chiffre d''affaires annuel se situe entre 1 million et 5 millions de RM sont entrées dans l''obligation, avec une période d''assouplissement (pas de sanctions pour erreurs de soumission) prolongée jusqu''au 31 décembre 2027.', '["Inscrivez-vous à l''accès au portail ou à l''API MyInvois auprès de la LHDN","Déterminez votre phase à partir de vos comptes audités de l''exercice 2022 ou de votre première déclaration fiscale disponible","Les factures électroniques individuelles sont obligatoires au-delà de 10 000 RM — la facturation consolidée n''est plus autorisée pour ces montants"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('my-related', 'fr', 'Entreprises liées/filiales de groupes de 1 M RM ou plus', 'Les entreprises dont le chiffre d''affaires est inférieur à 1 million de RM mais qui sont des filiales ou des entreprises liées à un groupe de 1 million de RM ou plus doivent tout de même se conformer, quel que soit leur propre chiffre d''affaires.', '["Vérifiez la structure du groupe — le statut d''entreprise liée peut déclencher l''obligation même pour de petites entités","Enregistrez et testez l''intégration MyInvois bien avant l''échéance"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('in-threshold', 'fr', 'Facturation électronique GST obligatoire au-delà de ₹5 crore de chiffre d''affaires (en vigueur depuis août 2023)', 'Toute entreprise immatriculée à la GST dont le chiffre d''affaires annuel agrégé (AATO) dépasse ₹5 crore au cours d''un exercice depuis 2017-18 doit générer des factures électroniques avec un IRN valide pour les transactions B2B et d''exportation.', '["Vérifiez le chiffre d''affaires agrégé sur l''ensemble des GSTIN sous votre PAN — le seuil de ₹5 crore ne doit être dépassé qu''une seule fois","Inscrivez-vous auprès d''un portail d''enregistrement des factures (IRP) — einvoice1.gst.gov.in du NIC ou un IRP privé autorisé","Surveillez une éventuelle réduction du seuil à ₹2 crore, évoquée mais pas encore notifiée"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('in-30day', 'fr', 'Fenêtre de déclaration IRN de 30 jours (AATO ≥ ₹10 crore)', 'Les factures, notes de crédit et notes de débit de plus de 30 jours ne peuvent plus être déclarées à l''IRP pour la génération de l''IRN — elles seront rejetées d''office pour les contribuables dont l''AATO est égal ou supérieur à ₹10 crore.', '["Intégrez la fenêtre de déclaration de 30 jours dans votre processus comptes fournisseurs/clients","Activez l''authentification multifacteur sur le portail GST — obligatoire depuis avril 2025"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-fields', 'fr', 'Champs CBS/IBS requis sur NF-e/NFC-e/NFS-e (taux de test)', 'Avec le début de la réforme de la TVA duale au Brésil, les documents fiscaux électroniques doivent inclure les nouveaux champs CBS et IBS à des taux de test (0,9 % / 0,1 %) — sans impact financier pour l''instant, mais l''obligation légale d''inclure ces données s''applique déjà.', '["Mettez à jour les formats de facturation selon la Note Technique 2025.002-RTC (dernière version)","Testez dans l''environnement d''homologation de la SEFAZ avant la mise en service","Les contribuables Simples Nacional / MEI bénéficient d''un calendrier prolongé jusqu''en 2027"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-validate', 'fr', 'La validation des champs CBS/IBS commence — risque de rejet', 'Les systèmes d''autorisation commencent à valider rigoureusement les champs CBS/IBS ; les factures présentant des données manquantes ou incohérentes risquent un rejet automatique.', '["Vérifiez la sortie des factures pour vous assurer de groupes de données CBS/IBS/IS complets et cohérents","Résolvez rapidement tout rejet — les factures bloquées interrompent la circulation des marchandises"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-mandatory', 'fr', 'Obligation légale complète de déclaration pour le régime fiscal général', 'Selon la Note Technique 2025.002-RTC v1.40, les contribuables du régime fiscal général doivent déclarer les groupes IBS et CBS dans les NF-e et NFC-e avec plein effet légal.', '["Vérifiez que votre ERP/prestataire de facturation électronique a terminé les mises à jour de schéma requises","Rapprochez les données CBS/IBS déclarées avec vos registres comptables avant l''application complète"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-verifactu-corp', 'fr', 'Logiciel de facturation certifié VeriFactu — contribuables à l''impôt sur les sociétés', 'Les entreprises soumises à l''impôt sur les sociétés doivent utiliser un logiciel de facturation certifié VeriFactu (RRSIF) garantissant l''intégrité, la traçabilité et l''immutabilité des registres de facturation transmis à l''Agencia Tributaria (AEAT).', '["Vérifiez que votre logiciel de facturation est certifié VeriFactu et génère la chaîne de hachage et le code QR requis","Il s''agit d''une obligation distincte du mandat plus large de facturation électronique B2B Crea y Crece détaillé ci-dessous"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-verifactu-rest', 'fr', 'VeriFactu obligatoire — tous les autres contribuables', 'L''obligation VeriFactu s''étend à tous les autres contribuables tenus de conserver des registres de facturation, y compris les travailleurs indépendants et autres professionnels soumis à l''impôt sur le revenu des personnes physiques.', '["Indépendants/freelances : assurez-vous que le logiciel de facturation certifié est en place bien avant cette date","Les entreprises utilisant déjà le système de déclaration en temps réel SII sont exemptées de VeriFactu"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-b2b-large', 'fr', 'Facturation électronique B2B Crea y Crece — grandes entreprises (>8 M € de chiffre d''affaires)', 'La facturation électronique B2B structurée devient obligatoire pour les grandes entreprises dans le cadre de la loi Crea y Crece, échangée via des plateformes privées (avec copie obligatoire vers la plateforme d''État) ou la solution publique gratuite (SPFE), en parallèle de VeriFactu.', '["Choisissez une plateforme privée de facturation électronique (devant transmettre une copie au SPFE) ou utilisez directement la plateforme publique","Vérifiez les formats conformes à EN 16931 (UBL, Facturae, CII)","Déclarez le statut de la facture — acceptée, rejetée ou payée — à l''AEAT dans les 4 jours calendaires"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-b2b-all', 'fr', 'Facturation électronique B2B Crea y Crece — toutes les entreprises restantes', 'L''obligation de facturation électronique B2B s''étend aux PME, aux entrepreneurs individuels et à toutes les autres entreprises assujetties à la TVA, achevant la réforme espagnole de facturation électronique à double voie.', '["Finalisez le choix de plateforme et l''intégration bien avant l''échéance","L''arrêté ministériel définitif était encore en attente mi-2026 — vérifiez cette date à l''approche du moment venu"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uk-mandate', 'fr', 'Facturation électronique obligatoire pour toutes les factures soumises à la TVA (B2B et B2G)', 'Confirmé lors du budget 2025, toutes les entreprises assujetties à la TVA doivent émettre et recevoir des factures électroniques structurées pour les transactions B2B et B2G, selon un modèle Peppol décentralisé à quatre coins. La déclaration en temps réel à la HMRC ne fait pas partie de cette obligation initiale.', '["Vérifiez que votre logiciel comptable dispose d''une voie vers la facturation électronique basée sur Peppol","Surveillez la feuille de route complète de mise en œuvre et les normes techniques attendues lors du budget 2026","Entreprises d''Irlande du Nord : notez une éventuelle obligation supplémentaire antérieure, alignée sur l''UE, pour le commerce de marchandises à partir de juillet 2030"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ro-established', 'fr', 'Modèle de contrôle RO e-Factura obligatoire pour le B2B/B2G (en vigueur depuis juillet 2024)', 'La Roumanie applique un modèle de contrôle centralisé (CTC) : les factures B2B et B2G doivent être validées et scellées numériquement par l''ANAF via RO e-Factura avant d''avoir un effet légal. La déclaration B2C a suivi à partir de janvier 2025.', '["Vérifiez l''enregistrement à RO e-Factura et la génération de factures XML conformes à RO_CIUS","Le délai de transmission est de 5 jours ouvrés à compter de l''émission (raccourci depuis 5 jours calendaires en janvier 2026)"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ro-sme', 'fr', 'L''application complète s''étend aux petits contribuables (chiffre d''affaires <500 000 €)', 'Après un report confirmé, les petits contribuables dont le chiffre d''affaires est inférieur à 500 000 € sont désormais pleinement soumis à l''application et aux sanctions d''e-Factura, sur un pied d''égalité avec les grandes entreprises.', '["Standardisez les adresses des clients et les codes pays/ISO avant l''échéance","Vérifiez que votre outil de facturation applique la règle de transmission de 5 jours ouvrés"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uae-pilot', 'fr', 'Début de la phase pilote volontaire de facturation électronique', 'La participation volontaire a été ouverte avant l''obligation, permettant aux entreprises de tester sans risque la connectivité avec un Accredited Service Provider (ASP) et le format de facture PINT AE avant l''application des sanctions.', '["Envisagez de rejoindre le pilote volontaire pour résoudre les problèmes d''intégration ASP avant la phase obligatoire","Suivez les mises à jour des directives techniques de la Federal Tax Authority (FTA)"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uae-asp', 'fr', 'Échéance de désignation d''un ASP — entreprises ≥ 50 M AED de chiffre d''affaires', 'Les entreprises dont le chiffre d''affaires est égal ou supérieur à 50 millions AED doivent avoir désigné un Accredited Service Provider (ASP) avant la mise en service de janvier 2027 (échéance repoussée du 31 juillet 2026).', '["Sélectionnez et contractez un Accredited Service Provider accrédité par la FTA","Commencez les tests d''intégration PINT AE (UBL 2.1) avec votre ASP"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uae-phase1', 'fr', 'Mise en service obligatoire Phase 1 — chiffre d''affaires ≥ 50 M AED', 'La facturation électronique structurée devient obligatoire pour les grandes entreprises, transmise via un ASP sur le réseau Peppol au format PINT AE, avec une copie en temps réel déclarée à la FTA.', '["Achevez l''intégration ASP et les tests de bout en bout avant la mise en service","Assurez-vous que les factures comportent tous les champs de données exigés par la FTA — les PDF et le papier ne sont plus acceptés"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uae-phase2', 'fr', 'L''obligation s''étend à toutes les autres entreprises assujetties à la TVA', 'L''obligation de facturation électronique s''élargit pour couvrir toutes les entreprises assujetties à la TVA restantes pour les transactions B2B/B2G, avec des obligations spécifiques G2B/B2G à partir d''octobre 2027.', '["Vérifiez le statut d''immatriculation à la TVA et désignez un ASP bien avant cette date","Les transactions intragroupe au sein d''un même groupe TVA des Émirats arabes unis bénéficient d''une transition prolongée jusqu''au 1er janvier 2029"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('mx-cfdi', 'fr', 'Modèle de contrôle CFDI obligatoire (version actuelle CFDI 4.0)', 'Le Mexique exploite l''un des systèmes de contrôle de facturation électronique les plus matures au monde : chaque facture doit être validée et estampillée numériquement (timbrado) par un PAC autorisé avant d''être légalement valide, au format XML CFDI 4.0.', '["Assurez la connectivité PAC et la correspondance actualisée des champs CFDI 4.0 (Anexo 20) — le RFC/nom/régime fiscal du destinataire doit correspondre exactement aux données du SAT","Joignez les compléments requis le cas échéant (Carta Porte pour le transport de marchandises, Pagos pour les paiements échelonnés, Comercio Exterior pour les exportations)","Conservez les factures XML et les accusés de réception PAC pendant au moins 5 ans"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('mx-reform', 'fr', 'Réforme fiscale 2026 — exigences d''authenticité et d''application renforcées', 'Une réforme fiscale en vigueur depuis janvier 2026 a renforcé les pouvoirs d''application du SAT, ajoutant des contrôles d''authenticité plus stricts et une responsabilité pénale pour les CFDI falsifiés ou simulés.', '["Conservez des preuves justifiant l''authenticité des transactions — contrats, preuves de livraison, registres de paiement — car le SAT peut les demander sous 5 jours ouvrés","Révisez la documentation de défense des CFDI et les procédures d''annulation compte tenu des nouvelles dispositions de responsabilité pénale"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-ncereceive', 'fr', 'Organismes fédéraux tenus de recevoir des factures Peppol (en vigueur depuis juillet 2022)', 'Toutes les entités non constituées en société du Commonwealth (organismes fédéraux) sont tenues de recevoir des factures Peppol depuis le 1er juillet 2022. Il n''existe pas d''obligation générale B2B, mais l''adoption par les pouvoirs publics continue de s''accélérer.', '["Fournisseurs des organismes fédéraux : connectez-vous via un Access Point Peppol accrédité par l''ATO","Les factures livrées via Peppol peuvent être payées sous 5 jours au lieu des 20 jours habituels"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-30pct', 'fr', '30 % des factures des organismes fédéraux doivent être traitées via Peppol', 'Les entités non constituées en société du Commonwealth doivent traiter au moins 30 % des factures fournisseurs reçues via le réseau Peppol, en route vers une automatisation complète d''ici décembre 2026.', '["Si vous fournissez des organismes fédéraux australiens, vérifiez que votre facturation est compatible Peppol","Utilisez le format PINT A-NZ — seule norme prise en charge depuis le 15 mai 2025"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-automate', 'fr', 'Les organismes fédéraux doivent automatiser l''envoi et le traitement des factures électroniques', 'Les entités non constituées en société du Commonwealth doivent pouvoir traiter automatiquement les factures électroniques reçues et envoyer des factures électroniques, avec un reporting trimestriel des progrès à l''Australian Peppol Authority.', '["Vérifiez que votre dispositif de facturation électronique prend en charge un traitement entièrement automatisé, sans intervention manuelle","Les fournisseurs du gouvernement doivent s''attendre à des cycles de paiement plus rapides à mesure que l''automatisation se met en place"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nz-central', 'fr', 'Les organismes du gouvernement central tenus de recevoir des factures électroniques (en vigueur depuis mars 2022)', 'Tous les organismes publics centraux sont tenus de recevoir des factures Peppol depuis mars 2022, administré par le MBIE en tant qu''autorité Peppol de Nouvelle-Zélande.', '["Fournisseurs des organismes centraux : mettez en place la capacité de facturation Peppol via un Access Point accrédité"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nz-2000', 'fr', 'Les organismes traitant plus de 2 000 factures/an doivent envoyer et recevoir des factures électroniques', 'Les organismes publics traitant plus de 2 000 factures commerciales nationales par an doivent être pleinement capables d''envoyer et de recevoir des factures électroniques structurées, et de payer 95 % d''entre elles sous 5 jours ouvrés.', '["Vérifiez la conformité au format PINT A-NZ — obligatoire pour la facturation électronique gouvernementale depuis mai 2025","Vérifiez si votre client gouvernemental se situe dans ce seuil de volume"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nz-largesupplier', 'fr', 'Les grands fournisseurs (chiffre d''affaires >33 M NZD) doivent soumettre des factures électroniques au gouvernement', 'Les fournisseurs dont le chiffre d''affaires dépasse 33 millions NZD au cours de chacun des deux exercices comptables précédents doivent soumettre des factures électroniques via Peppol pour les factures de commerce national aux acheteurs gouvernementaux.', '["Évaluez si votre chiffre d''affaires dépasse le seuil de 33 millions NZD","Intégrez-vous à un Access Point Peppol bien avant l''échéance"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-voluntary2025', 'fr', 'GST InvoiceNow obligatoire — nouveaux immatriculés volontaires à la GST (dans les 6 mois suivant la constitution)', 'La première phase obligatoire de GST InvoiceNow exigeait des entreprises s''étant immatriculées volontairement à la GST dans les six mois suivant leur constitution de transmettre les données de facturation à l''IRAS via le réseau InvoiceNow basé sur Peppol.', '["Nouveaux immatriculés GST éligibles : mettez en place une solution InvoiceNow-Ready et un identifiant Peppol dès l''immatriculation"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-allvoluntary', 'fr', 'L''obligation s''étend à tous les nouveaux immatriculés volontaires à la GST', 'Tous les nouveaux immatriculés volontaires à la GST, quelle que soit la date de constitution ou la structure de l''entreprise, doivent adopter InvoiceNow comme condition d''immatriculation à la GST.', '["Intégrez la mise en place d''InvoiceNow dans votre demande d''immatriculation à la GST à partir de cette date","Utilisez le calculateur de date de mise en œuvre de l''IRAS en cas de doute sur la phase applicable"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-existing2028', 'fr', 'Début du déploiement par étapes pour les entreprises déjà immatriculées à la GST', 'Les entreprises déjà immatriculées à la GST commencent à être intégrées à GST InvoiceNow selon un calendrier par étapes menant à l''adoption complète en 2031. L''IRAS notifiera aux entreprises concernées leur date spécifique durant 2026.', '["Utilisez le calculateur de date de mise en œuvre GST InvoiceNow de l''IRAS pour déterminer votre date applicable","Surveillez la notification directe de l''IRAS (attendue d''ici mi-2026)"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-full2031', 'fr', 'Adoption complète — toutes les entreprises immatriculées à la GST', 'D''ici cette date, chaque entreprise immatriculée à la GST à Singapour, y compris les grandes multinationales, doit transmettre les données de facturation via InvoiceNow.', '["Planifiez l''intégration bien à l''avance — des subventions publiques transitoires sont disponibles pour soutenir l''adoption"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sk-voluntary', 'fr', 'Début de la période de transition volontaire pour la facturation/déclaration électronique', 'Les entreprises peuvent s''inscrire volontairement pour tester la facturation électronique structurée et la déclaration avant l''obligation de janvier 2027, selon un modèle décentralisé « à 5 coins » basé sur Peppol.', '["Inscrivez-vous à la participation volontaire auprès de l''Administration financière pour tester les intégrations tôt","Vérifiez que votre logiciel comptable peut générer du XML UBL Peppol BIS 3.0"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sk-mandate', 'fr', 'Facturation électronique B2B/B2G nationale obligatoire et déclaration quasi en temps réel', 'La facturation électronique structurée et la déclaration en temps réel deviennent obligatoires pour les transactions B2B et B2G nationales entre contribuables slovaques à la TVA, via des points d''accès certifiés « Digital Postman » sur un réseau basé sur Peppol.', '["Sélectionnez un fournisseur Digital Postman approuvé (point d''accès certifié)","À partir de 2027, la TVA déductible ne pourra plus être récupérée sur les factures entrantes non conformes","Remarque : la facturation électronique transfrontalière suivra plus tard, selon le calendrier ViDA de l''UE à partir de juillet 2030"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pe-established', 'fr', 'Facturation électronique (CPE) obligatoire pour tous les contribuables (en vigueur depuis juin 2022)', 'Le Pérou exploite l''un des systèmes de facturation électronique les plus matures d''Amérique latine. Les reçus de paiement électroniques (CPE) doivent être émis en XML UBL 2.1, signés numériquement et validés par la SUNAT ou un Opérateur de Services Électroniques (OSE) autorisé avant d''être légalement valides.', '["Utilisez un fournisseur de services électroniques (PSE) agréé pour générer et signer les CPE","Envoyez les factures électroniques à la SUNAT dans les 3 jours calendaires suivant l''émission","Archivez les factures XML et les confirmations de réception CDR pendant au moins 5 ans"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cl-established', 'fr', 'Documents fiscaux électroniques (DTE) obligatoires pour toutes les entreprises (en vigueur depuis 2018)', 'Toutes les entreprises chiliennes doivent émettre des Documentos Tributarios Electrónicos (DTE) — y compris les facturas (B2B) et les boletas (B2C) — validés par le Servicio de Impuestos Internos (SII).', '["Vérifiez que votre système d''émission de DTE est autorisé et connecté au SII","Pour les ventes supérieures à 135 UF, la boleta électronique doit identifier l''acheteur par son RUT et son nom"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cl-digital-delivery', 'fr', 'Livraison numérique de la boleta électronique requise en l''absence d''imprimante', 'Les entreprises sans capacité d''impression doivent livrer la boleta électronique numériquement — par e-mail, SMS, WhatsApp, code QR ou tout autre canal électronique équivalent — plutôt que de renoncer totalement à la livraison.', '["Si vous ne disposez pas d''impression au point de vente, mettez en place dès maintenant un canal de livraison électronique (e-mail/SMS/QR)","Les entreprises disposant d''imprimantes doivent généralement continuer à fournir la représentation imprimée"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ie-phase1', 'fr', 'Phase 1 — les grandes entreprises doivent émettre des factures électroniques ; toutes les entreprises doivent pouvoir les recevoir', 'Les grandes entreprises assujetties à la TVA gérées par la division des grandes entreprises de Revenue doivent émettre des factures électroniques structurées et déclarer un sous-ensemble de données de transaction pour les ventes B2B nationales. À partir de cette date, toutes les entreprises doivent être techniquement capables de recevoir des factures électroniques structurées.', '["Grandes entreprises : évaluez dès maintenant la préparation de l''ERP pour la facturation structurée EN 16931 via Peppol","Toutes les entreprises : vérifiez que vos systèmes peuvent recevoir des factures électroniques structurées — les PDF ne seront plus acceptés des fournisseurs concernés"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ie-phase2', 'fr', 'Phase 2 — l''obligation s''étend à toutes les entreprises assujetties à la TVA dans le commerce intracommunautaire', 'L''obligation nationale de facturation électronique et de déclaration s''étend à toutes les entreprises restantes assujetties à la TVA engagées dans le commerce B2B transfrontalier au sein de l''UE, avant la pleine conformité ViDA de l''UE en juillet 2030.', '["Les entreprises pratiquant le commerce transfrontalier au sein de l''UE devraient commencer à planifier l''intégration Peppol","Surveillez les directives détaillées de Revenue, attendues bien avant chaque phase"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('no-issue', 'fr', 'Émission obligatoire de factures électroniques B2B (EHF 3.0 / Peppol BIS)', 'Suite à l''adoption des modifications de la loi sur la comptabilité, toutes les entreprises soumises aux obligations comptables norvégiennes doivent émettre des factures électroniques structurées (format EHF) à d''autres entreprises inscrites dans l''annuaire ELMA.', '["Inscrivez-vous à ELMA (l''annuaire norvégien des destinataires Peppol) si ce n''est pas déjà fait","Vérifiez que votre logiciel de facturation prend en charge la sortie EHF 3.0 / Peppol BIS","Les factures B2B en PDF et papier ne seront plus valables pour les transactions concernées"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('no-receive', 'fr', 'Réception obligatoire de factures électroniques et comptabilité entièrement numérique', 'L''obligation s''étend à la réception de factures électroniques structurées et à la tenue de registres comptables entièrement numériques, achevant la réforme norvégienne en deux phases.', '["Planifiez la migration vers un système de comptabilité numérique approuvé bien avant cette date","Vérifiez que les systèmes de comptes fournisseurs peuvent recevoir et traiter automatiquement les factures EHF/Peppol"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('dk-established', 'fr', 'Loi sur la comptabilité numérique appliquée — moyennes/grandes entreprises (en vigueur depuis juillet 2024)', 'Les moyennes et grandes entreprises déposant des rapports annuels doivent utiliser un système de comptabilité numérique certifié capable d''envoyer et de recevoir des factures électroniques structurées (OIOUBL ou Peppol BIS 3.0) et de générer des fichiers SAF-T sur demande.', '["Vérifiez que votre système comptable figure sur la liste certifiée de l''Autorité danoise des entreprises, ou assurez vous-même la conformité si vous utilisez un système personnalisé","Conservez des registres numériques pendant 5 ans avec sauvegarde automatisée hors site"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('dk-small', 'fr', 'Les petites entreprises (chiffre d''affaires >300 000 DKK) utilisant des systèmes personnalisés doivent se conformer', 'Les petites entreprises et entreprises individuelles dépassant 300 000 DKK de chiffre d''affaires sur deux années consécutives, utilisant des systèmes comptables non enregistrés (« personnalisés »), sont désormais pleinement soumises aux exigences numériques de la loi sur la comptabilité.', '["Vérifiez si votre chiffre d''affaires a dépassé le seuil de 300 000 DKK au cours des deux derniers exercices","Les entreprises utilisant des systèmes enregistrés/certifiés devaient déjà se conformer depuis janvier 2026"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('se-b2g', 'fr', 'Facturation électronique B2G obligatoire pour toutes les entités publiques (en vigueur depuis 2019)', 'Toutes les autorités adjudicatrices et entités publiques en Suède doivent pouvoir recevoir des factures électroniques conformes à EN 16931, Peppol BIS Billing 3.0 étant le format recommandé (et de plus en plus exigé) à mesure que les formats hérités comme Svefaktura sont progressivement abandonnés.', '["Fournisseurs des entités publiques suédoises : utilisez Peppol BIS Billing 3.0 dans la mesure du possible — les formats hérités SFTI/EDIFACT sont progressivement retirés","Aucune obligation nationale B2B n''existe encore — voir l''entrée ci-dessous sur l''alignement attendu avec l''UE"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('se-b2b-expected', 'fr', 'Facturation électronique B2B transfrontalière attendue sous ViDA de l''UE', 'La Suède n''a pas encore légiféré sur une obligation nationale de facturation électronique B2B ; Skatteverket, DIGG et Bolagsverket ont demandé au gouvernement d''en évaluer une, mais la seule échéance ferme actuellement sur la table est l''obligation transfrontalière ViDA à l''échelle de l''UE.', '["Surveillez toute annonce d''obligation nationale — une proposition gouvernementale formelle est encore en attente","Les entreprises pratiquant le commerce transfrontalier devraient tout de même planifier leur préparation EN 16931/Peppol avant l''échéance de 2030 à l''échelle de l''UE"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cn-nationwide', 'fr', 'La facture électronique entièrement numérisée (e-fapiao) déployée à l''échelle nationale (en vigueur depuis décembre 2024)', 'L''Administration fiscale d''État (STA) a achevé le déploiement national des factures électroniques entièrement numérisées (e-fapiao), leur conférant la même validité légale que les factures papier et remplaçant les précédentes phases pilotes du Golden Tax System.', '["Créez un compte fiscal numérique auprès de la STA pour émettre et recevoir des e-fapiao","Vérifiez que les systèmes ERP/facturation peuvent produire des e-fapiao avec les champs obligatoires en chinois simplifié et le rendu OFD/XML","Conservez le code de facture STA, la signature numérique, le code QR dynamique et l''horodatage de validation de chaque facture"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cn-paper-phaseout', 'fr', 'L''abandon régional des factures papier s''accélère', 'Les administrations fiscales locales de plusieurs régions (par exemple Dalian, avec effet au 1er juillet 2026) ont commencé à abandonner certains types de factures papier sous contrôle fiscal au profit de l''e-fapiao, d''autres régions devant suivre en 2026.', '["Consultez les annonces de votre antenne locale de la STA concernant les dates d''abandon du papier propres à votre région et secteur","Les factures émises avant la date limite d''une région restent valables, mais la nouvelle émission de factures papier peut être bloquée à partir de cette date"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('hr-b2b', 'fr', 'Fiskalizacija 2.0 — facturation et déclaration électroniques obligatoires pour les entreprises assujetties à la TVA', 'La réforme croate de « Fiscalisation 2.0 » a rendu obligatoires la facturation électronique structurée (émission et réception) et la déclaration électronique en temps réel pour tous les contribuables croates assujettis à la TVA, en plus de l''obligation de facturation électronique B2G déjà en vigueur depuis 2019.', '["Enregistrez une adresse AMS et contractez un intermédiaire d''information ou un point d''accès certifié","Assurez-vous que les systèmes ERP produisent du XML UBL 2.1 valide conforme au CIUS HR-FISK 2.0 (y compris les codes KPD à 6 chiffres et les OIB)","Intégrez le processus de fiscalisation à 5 jours côté acheteur et la déclaration électronique mensuelle avant le 20","Archivez les factures XML originales pendant 11 ans"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('hr-nonvat', 'fr', 'L''obligation s''étend aux entités non assujetties à la TVA et aux organismes publics', 'L''obligation d''émettre (pas seulement de recevoir) des factures électroniques structurées et des données de déclaration électronique s''étend aux entités non assujetties à la TVA — petites entreprises, indépendants et certains organismes publics/budgétaires.', '["Entreprises et indépendants non assujettis à la TVA : vérifiez la capacité d''émission de factures électroniques bien avant cette date","Les organismes publics non assujettis à la TVA devraient achever l''intégration au point d''accès durant 2026"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('us-federal-b2g', 'fr', 'Les organismes fédéraux tenus de gérer les factures électroniquement (B2G, en vigueur depuis 2018)', 'L''Office of Management and Budget a demandé aux organismes fédéraux de passer à la facturation électronique pour les achats appropriés. La plupart utilisent désormais la plateforme de traitement des factures (IPP) du Trésor — mais il n''existe aucun format unique imposé, ni aucune obligation nationale B2B de quelque nature que ce soit.', '["Si vous vendez à des organismes fédéraux, vérifiez que vous êtes configuré sur l''IPP ou le canal de facturation électronique désigné par votre organisme","Conservez les registres de factures électroniques de manière à ce qu''ils restent accessibles, exacts et lisibles conformément aux directives de l''IRS (publication 583)"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('us-dbnalliance', 'fr', 'Réseau d''échange de factures électroniques B2B DBNAlliance actif (volontaire, porté par le marché)', 'La Digital Business Networks Alliance (DBNAlliance) — une organisation à but non lucratif issue d''un pilote de la Réserve fédérale / Business Payments Coalition — exploite désormais un réseau à quatre coins de type Peppol pour l''échange volontaire et structuré de factures électroniques B2B aux États-Unis et au Canada. Aucune loi fédérale ou étatique n''impose son adoption.', '["Envisagez de vous connecter via un prestataire certifié DBNAlliance avant toute future obligation","Si vous commercez avec des partenaires dans des pays imposant déjà la facturation électronique (UE, Mexique, Brésil, etc.), assurez-vous que vos systèmes peuvent toujours produire leurs formats requis"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ca-federal-b2g', 'fr', 'Tous les fournisseurs du gouvernement fédéral doivent facturer électroniquement (B2G, en vigueur depuis 2022)', 'Depuis avril 2022, Services publics et Approvisionnement Canada (SPAC) exige des fournisseurs qu''ils soumettent leurs factures électroniquement via sa solution d''approvisionnement électronique basée sur SAP Ariba. Il n''existe aucune obligation fédérale de facturation électronique B2B.', '["Si vous fournissez le gouvernement du Canada, inscrivez-vous à SAP Ariba via CanadaBuys","Conservez les factures électroniques pendant au moins 6 ans conformément aux exigences de conservation des registres de l''ARC"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ca-watch', 'fr', 'L''ARC étudie une éventuelle obligation de facturation électronique B2B (aucune obligation adoptée)', 'L''Agence du revenu du Canada a mené une étude auprès des parties prenantes sur une éventuelle obligation nationale de facturation électronique B2B. Aucune législation ni calendrier ferme n''a suivi — les règles de TPS/TVH restent neutres quant au format, et les factures papier, PDF et EDI sont actuellement toutes acceptables dès lors qu''elles comportent les informations fiscales requises.', '["Aucune action n''est requise aujourd''hui au-delà de bonnes pratiques de tenue de registres","Surveillez les futures annonces de l''ARC / Finances Canada, notamment à mesure que l''adoption du réseau DBNAlliance progresse au Canada"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-b2g-large', 'fr', 'Facturation électronique B2G obligatoire pour les grandes entreprises (en vigueur depuis janvier 2021)', 'Les grandes entreprises fournissant des organismes de l''administration publique doivent émettre des factures électroniques structurées au format national CIUS-PT (une mise en œuvre portugaise de la norme EN 16931, via UBL 2.1 ou CEFACT CII), transmises via la plateforme FE-AP gérée par l''eSPap ou un autre canal approuvé. Le Portugal n''a pas d''obligation générale de facturation électronique B2B ou B2C — cette exigence s''applique spécifiquement à l''approvisionnement du secteur public.', '["Confirmez que votre système de facturation peut générer un XML structuré CIUS-PT valide, pas seulement une représentation PDF","Connectez-vous à FE-AP ou à un canal alternatif approuvé pour transmettre les factures aux organismes publics"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-b2g-sme', 'fr', 'L''obligation B2G s''étend aux petites, moyennes et micro-entreprises', 'L''exigence de facturation électronique structurée CIUS-PT pour les fournisseurs du secteur public, auparavant limitée aux grandes entreprises, s''étend désormais aux petites, moyennes et micro-entreprises. Par ailleurs, indépendamment de la taille de l''entreprise ou de l''applicabilité du B2G, toutes les factures — papier ou électroniques — doivent déjà être émises à l''aide d''un logiciel certifié par l''AT et porter un code ATCUD, un code QR et une chaîne de hachage garantissant l''authenticité.', '["Si vous fournissez un organisme public portugais et n''émettez pas encore de factures structurées CIUS-PT, il s''agit désormais d''un écart de conformité actif, non futur","Indépendamment de votre statut B2G, confirmez que votre logiciel de facturation figure sur la liste certifiée par l''AT — l''utilisation d''un logiciel non certifié invalide une facture quel que soit son contenu"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-qes', 'fr', 'La Signature Électronique Qualifiée (QES) requise pour les factures PDF', 'Les factures PDF dans les transactions B2B et B2C nécessiteront une Signature Électronique Qualifiée d''un prestataire de services de confiance qualifié inscrit sur liste européenne pour rester légalement valables — reportée d''une date initiale de 2026 via le Budget de l''État 2026. Jusqu''au 31 décembre 2026, les factures PDF émises par un logiciel certifié avec ATCUD et code QR restent valables sans QES. Cette couche s''applique en plus de, et non à la place de, les exigences déjà en vigueur en matière de logiciel certifié/ATCUD/QR/SAF-T.', '["Identifiez un prestataire de services de confiance qualifié inscrit sur liste européenne pour la QES bien avant l''échéance de 2027 — il s''agit d''une étape d''approvisionnement distincte, pas d''un simple paramètre logiciel","Ne supposez pas que la conformité aux exigences existantes ATCUD/QR/logiciel certifié couvre déjà cela — la QES est une couche véritablement nouvelle et supplémentaire spécifique aux factures PDF"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fi-b2g', 'fr', 'Facturation électronique B2G obligatoire (en vigueur depuis avril 2020)', 'Tous les fournisseurs facturant des organismes gouvernementaux finlandais doivent envoyer des factures électroniques sauf accord contraire — l''un des régimes B2G les plus matures d''Europe, avec environ 99 % des factures aux acheteurs publics déjà électroniques. La Finlande n''a pas d''obligation générale de facturation électronique B2B ou B2C : la facturation électronique B2B nationale reste entièrement volontaire, bien que les entreprises dont le chiffre d''affaires dépasse 10 000 € disposent d''un droit légal d''exiger des factures électroniques de leurs fournisseurs en vertu de la loi sur la facturation électronique 241/2019.', '["Si vous fournissez un organisme public finlandais, confirmez que vous pouvez envoyer des factures électroniques — c''est la norme depuis des années, pas une nouvelle exigence","Pour le B2B national, ne supposez pas qu''une obligation légale existe — vérifiez plutôt les exigences contractuelles propres à votre client"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fi-en-standard', 'fr', 'L''État exige des factures électroniques conformes à l''EN 16931 (en vigueur depuis avril 2021)', 'À partir de cette date, les organismes gouvernementaux finlandais n''acceptent plus que les factures électroniques conformes à la norme européenne (EN 16931) — les formats non standard ne suffisent plus pour la facturation B2G, alors même que la facturation électronique elle-même était déjà obligatoire depuis un an. Finvoice 3.0 et TEAPPSXML 3.0 peuvent tous deux produire des factures conformes à l''EN, mais la conformité n''est pas automatique — les entreprises doivent vérifier que la sortie de leur logiciel respecte réellement la norme, sans la supposer par défaut.', '["Confirmez que la sortie Finvoice 3.0 ou TEAPPSXML 3.0 de votre logiciel est réellement conforme à l''EN 16931, pas seulement superficiellement similaire","Consultez l''annuaire Verkkolaskuosoite pour confirmer quel opérateur/portail de facturation électronique permet d''atteindre un interlocuteur donné du secteur public — il n''existe pas de plateforme centrale unique"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fi-vida', 'fr', 'Facturation électronique B2B intracommunautaire obligatoire au titre du ViDA de l''UE', 'La Finlande n''a actuellement aucune obligation nationale de facturation électronique B2B, et aucune n''est confirmée avant cette échéance à l''échelle de l''UE, en vertu de laquelle les transactions B2B intracommunautaires nécessiteront une facturation électronique structurée et une déclaration numérique dans tous les États membres. Le gouvernement finlandais a indiqué qu''il prévoyait de commencer les préparatifs autour de 2028, et une obligation nationale pourrait suivre cette échéance de l''UE plutôt que la précéder — une posture véritablement différente de celle de la plupart des autres pays de l''UE dans ce suivi, qui devancent largement le plancher de l''UE de 2030.', '["Ne supposez pas que la Finlande suivra le même calendrier d''obligation nationale que ses voisins nordiques — à ce jour, aucune date d''obligation nationale n''a été fixée","Consultez cette page périodiquement plutôt que de considérer l''absence actuelle d''obligation comme un état permanent — les préparatifs de 2028 pourraient faire apparaître un calendrier national plus ferme"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('lx-b2g', 'fr', 'L''obligation de facturation électronique B2G est pleinement en vigueur', 'Le déploiement progressif de la facturation électronique B2G au Luxembourg est achevé : tous les opérateurs économiques, y compris les petites entreprises et celles nouvellement créées, doivent désormais émettre des factures électroniques Peppol BIS Billing 3.0 / EN 16931 aux organismes publics luxembourgeois.', '["Vérifiez que votre Access Point Peppol (ou l''option de téléversement manuel de guichet.lu) est configuré pour chaque marché public que vous fournissez","Des factures structurées EN 16931 sont exigées pour l''ensemble des marchés publics — aucun seuil ne s''applique"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('lx-b2b-receipt', 'fr', 'Proposition : la réception de factures électroniques B2B devient obligatoire', 'Selon le projet de loi approuvé par le Conseil de gouvernement luxembourgeois le 17 juillet 2026, toutes les entreprises seraient tenues de pouvoir recevoir des factures électroniques structurées pour les transactions B2B nationales via un réseau Peppol à quatre coins, avant l''obligation d''émission.', '["Suivez l''évolution du projet de loi au Parlement — il ne s''agit encore que d''un projet, non encore en vigueur","Vérifiez que votre système de facturation/ERP peut déjà recevoir des factures Peppol BIS Billing 3.0"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('lx-b2b-issue-large', 'fr', 'Proposition : émission de factures électroniques B2B pour les grandes et moyennes entreprises', 'Les grandes et moyennes entreprises seraient tenues d''émettre, et pas seulement de recevoir, des factures électroniques B2B nationales structurées via Peppol — six mois après l''entrée en vigueur de l''obligation de réception pour tous.', '["Fournisseurs de grande taille : commencez l''intégration à un Access Point Peppol bien avant cette date","Vérifiez votre classification actuelle par taille d''entreprise, car elle détermine l''échéance applicable"]');
INSERT OR REPLACE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('lx-b2b-issue-all', 'fr', 'Proposition : l''émission de factures électroniques B2B devient universelle', 'Les entreprises restantes, y compris les PME, seraient tenues d''émettre des factures électroniques B2B nationales structurées, achevant ainsi le déploiement progressif annoncé dans le cadre des réformes européennes de la TVA à l''ère numérique (ViDA).', '["PME : c''est l''échéance qui vous concerne, 18 mois après le début de l''obligation de réception","Aucune déclaration de TVA nationale en temps réel n''est prévue en parallèle — le Luxembourg conserve le modèle d''interopérabilité Peppol plutôt qu''un système de contrôle centralisé"]');
